/**
 * Diccionario de datos de las tablas de seguros (Circular CMF 1835).
 * Archivo GENERADO por seguros/scripts/diccionario_1835.py — no editar a mano.
 * Cada columna sale de los anexos técnicos de la Circular 1835, con el nombre
 * original de la CMF, su tipo, la unidad y la descripción literal de la ficha.
 * Lo usa la descarga de Excel para agregar la hoja "Diccionario" a los datos.
 */
window.DICCIONARIO_SEGUROS = {"acciones":{"cabecera":["columna","tipo","unidad","nombre en la ficha CMF","registro","vigencia","descripción"],"filas":[["periodo","VARCHAR","","","","ambos","Mes de la cartera informada (AAAA-MM)."],["sector","VARCHAR","","","","ambos","vida (archivos CSVID) o generales (CSGEN)."],["rut_aseguradora","VARCHAR","","","","ambos","RUT de la compañía de seguros, con dígito verificador (une con seguros.lista_entidades)."],["nombre_aseguradora","VARCHAR","","","","ambos","Nombre de la compañía tal como aparece en el encabezado del archivo del mes."],["rut","VARCHAR","","RUT","a2","ambos","Se deberá informar el RUT del emisor de cada título, o el RUT de la administradora del fondo"],["run","VARCHAR","","RUN","a2","ambos","Se deberá informar el RUN del fondo que forma parte de las inversiones de cada compañía, de acuerdo a la codificación definida en SEIL, codificación S.V.S., Fondos de Inversión. Para el caso de acciones de sociedades anónimas se informara con ceros"],["tipo_instrumento","VARCHAR","","TIPO_INSTRUMENTO","a2","ambos","Este campo es obligatorio y se informará de acuerdo a la codificación definida en SEIL, codificación S.V.S., Instrumentos"],["nemotecnico","VARCHAR","","NEMOTECNICO","a2","ambos","Corresponde informar el código nemotécnico, de acuerdo a las instrucciones impartidas por Circular N° 1085 o la que la reemplace, utilizado para identificar el instrumento cuando se trate de acciones nacionales transadas en el mercado nacional o cuotas de fondos. Para acciones de empresas nacionales transadas en mercados internacionales, se debe informar el código universal “ISIN” (Internacional Securities Identification Number) a falta de éste, el código “CUSIP” (Comité On Uniform Securities Identification Procedures) y de no existir los anteriores, se deberá consultar a esta Superintendencia. En el caso de acciones de sociedades anónimas cerradas, se deberá informar el nombre de la sociedad"],["serie","VARCHAR","","SERIE","a2","ambos","Se deberá informar la serie del instrumento cuando corresponda"],["unidades","DOUBLE","","UNIDADES","a2","ambos","Corresponde informar el número de acciones o cuotas, propiedad de la entidad a la fecha de cierre del mes a que se refiere la información, agrupando todas las compras correspondientes al mismo emisor, fondo de inversión y serie, cuando corresponda"],["pres_bursatil","DOUBLE","","PRES_BURSATIL","a2","ambos","Corresponde informar la presencia bursátil de la acción o fondo, propiedad de la compañía, a la fecha de cierre del mes a que se refiere la información. Si no cuenta con presencia bursátil, se informará con ceros (0)"],["valor_costo_clp","BIGINT","pesos","VALOR_COSTO","a2","ambos","Corresponde al precio pagado por las acciones o por las cuotas de fondos de inversión, más los gastos asociados, tales como comisiones e impuestos (exceptos aquellos recuperables), a la fecha de cierre del mes a que se refiere la información. Este monto se deberá expresar en pesos ($)"],["valor_libro_clp","BIGINT","pesos","VALOR_LIBRO","a2","ambos","Corresponde al valor libro unitario de una acción o al valor contable unitario de la cuota, por el número de UNIDADES. El valor libro unitario corresponde al patrimonio de la emisora (o fondo) dividido por el número total de acciones (o cuotas) pagadas a la fecha de cierre del mes a que se refiere la información, este monto se deberá expresar en pesos ($). Para el caso de las acciones registradas con presencia ajustada anual igual o superior al 25 % este valor deberá informarse en cero"],["valor_bolsa_clp","BIGINT","pesos","VALOR_BOLSA","a2","ambos","Corresponde al valor bolsa de la cuota o de la acción definido en Circular de Valorización, multiplicado por el número de UNIDADES, este monto se deberá expresar en pesos ($). Para el caso de sociedades anónimas cerradas o cuotas de fondos que no tengan valor bolsa, se deberá informar con ceros"],["valor_razonable_m_clp","BIGINT","miles de pesos","VALOR_RAZONABLE","a2","ambos","Corresponde al valor de mercado del instrumento a la fecha de la información. Se debe presentar en M$. Para las inversiones que no se transen en un mercado primario o secundario, se deberá informar una estimación del valor de mercado realizada por la compañía"],["deterioro_m_clp","BIGINT","miles de pesos","DETERIORO","a2","ambos","Corresponde al deterioro de la inversión, según lo señalado en la Norma de Carácter General N°311, del 28.06.2011. Este monto deberá expresarse en miles de pesos (M$)"],["provision_voluntaria_clp","BIGINT","pesos","PROVISION_VOLUNTARIA","a2","ambos","Corresponde a la provisión voluntaria que pueden efectuar las entidades aseguradoras o reaseguradoras de acuerdo a lo indicado en la Circular de Valorización de Inversiones, en pesos ($)"],["valor_final_m_clp","BIGINT","miles de pesos","VALOR_FINAL","a2","ambos","Corresponde al valor que tiene el instrumento a la fecha de cierre del mes a que se refiere la información, según lo establecido en Circular de Valorización de Inversiones vigente. Este monto se deberá expresar en miles de pesos (M$)"],["unidad_monetaria","VARCHAR","","UNIDAD_MONETARIA","a2","ambos","Corresponde informar la unidad monetaria o moneda de origen de la acción o cuota. Se informará de acuerdo a la codificación definida en SEIL"],["ajuste_a_valor_economico","VARCHAR","","AJUSTE_A_VALOR_ECONOMICO","a2","ambos","Corresponde indicar si la valorización de la cuota del fondo es ajustada a valor económico. Se informará de acuerdo a la siguiente codificación: S : Ajustado N : No ajustado Si no corresponde informar, se llenará con espacios"],["prohibicion","VARCHAR","","PROHIBICION","a2","ambos","Corresponde informar si los títulos registrados se encuentran afectos a prohibiciones, gravámenes u otros impedimentos señalados en el DFL Nº251. Se informará de acuerdo a la siguiente codificación: S : Si tiene prohibición. N : No tiene prohibición"],["activo_en_margen","VARCHAR","","ACTIVO_EN_MARGEN","a2","ambos","Corresponde informar si uno o más títulos registrados (en caso de haber agrupado instrumentos con características idénticas) se encuentran otorgados como margen de las operaciones de derivado señaladas en el DFL Nº251. Cuando el instrumento se encuentre en margen, se informará el tipo de contrato al cual está asociado utilizando la codificación definida en el SEIL, Codificación S.V.S., Instrumentos Derivados y Pactos. Si no está en margen se informará N"],["unidades_en_margen","DOUBLE","","UNIDADES_EN_MARGEN","a2","ambos","Corresponde informar el número de acciones o cuotas de fondos que se encuentran otorgados como margen de las operaciones de derivados señaladas en el DFL Nº251"],["accion_en_prestamo","VARCHAR","","ACCION_EN_PRESTAMO","a2","ambos","Corresponde informar si una o más acciones registradas se encuentran, prestadas por la compañía, en operaciones de venta corta. Se informará de acuerdo a la siguiente codificación: S : acción afecta a préstamo por operación de venta corta. N : acción no afecta a préstamo por operación de venta corta"],["unidades_en_prestamo","BIGINT","","UNIDADES_EN_PRESTAMO","a2","ambos","Corresponde informar el número de acciones prestadas por la compañía, en operaciones de venta corta"],["activo_respalda_reserva_valor_de_fondo","VARCHAR","","ACTIVO_RESPALDA_RESERVA_VALOR_DE_FONDO","a2","ambos","Corresponde informar si uno o más títulos (en caso de haber agrupado instrumentos con características idénticas) registrados, se encuentran respaldando la reserva de valor del fondo señalada en el DFL Nº251. Se informará de acuerdo a la valorización que tengan los títulos, según Circular N°1360 y posteriores modificaciones, con un código de cinco letras formado de la siguiente manera: Las tres primeras letras serán: APV : si los instrumentos respaldan la reserva de valor del fondo de seguros con ahorro previsional voluntario, o OTR : si los instrumentos respaldan la reserva de valor del fondo de seguros con ahorro, distinto a los seguros con ahorro previsional voluntario La cuarta letra será A, B, C o D dependiendo de la forma de constitución de la reserva de descalce a que se refiere el N°4 de la Norma de Carácter General N°132, de 13 de marzo de 2002 y sus posteriores modificaciones. Para las Cuotas de Fondos de Inversión, la quinta letra será:"],["nombre_del_fondo","VARCHAR","","NOMBRE_DEL_FONDO","a2","ambos","Para instrumentos que estén asociados a fondos que respalden seguros de vida con cuenta de inversión, se debe informar el nombre del Fondo al cual pertenece. Se entenderá por fondo al tipo de plan o modalidades de inversión convenidos para los seguros con cuentas de inversión. Para instrumentos que no respalden seguros de vida con cuenta de inversión, se debe informar “NO APLICA”"],["nombre_cartera","VARCHAR","","NOMBRE_CARTERA","a2","ambos","Para instrumentos que no respalden seguros de vida con cuenta de inversión, se debe informar la sub cartera que respalda, si corresponde. Para instrumentos que no respalden una sub cartera, se debe informar “NO APLICA”"],["custodia_inv","VARCHAR","","CUSTODIA_INV","a2","ambos","Corresponde informar para cada instrumento, el tipo de custodia que presenta, de acuerdo a la siguiente codificación: CIA : Custodia en Compañía. DCV : Custodia en DCV, solo si la Cía. actuó como Depositante. EXT : Custodia en Otra entidad"],["nombre_custodio","VARCHAR","","NOMBRE_CUSTODIO","a2","ambos","Corresponde informar el nombre de la entidad que custodia la inversión en el evento que se informe en el campo CUSTODIA_INV, el código EXT (otra entidad de custodia). En caso de que no corresponda informar, se deberá llenar con espacios este campo"],["susceptibles_de_custodia","VARCHAR","","SUSCEPTIBLES_DE_CUSTODIA","a2","ambos","Se deberá informar si el instrumento es susceptible de ser custodiado de acuerdo a lo dispuesto en Circular N° 88 del Depósito Central de Valores S.A., y sus modificaciones posteriores, de acuerdo a la siguiente codificación: S: es susceptible de ser custodiado. N: no es susceptible de ser custodiado"],["relacionado","VARCHAR","","RELACIONADO","a2","ambos","Corresponde informar si el emisor del instrumento está relacionado con la compañía de seguros, de acuerdo a lo establecido en el artículo N°100 de la ley N°18.045 del 22.10.1981 y sus modificaciones. Se señalará de acuerdo a la siguiente codificación: RE : Relacionado NR : No Relacionado"],["filial_coligada","VARCHAR","","FILIAL_COLIGADA","a2","ambos","Se debe informar si la inversión informada corresponde a una empresa Filial o Coligada de acuerdo a la circular 2022, utilizando la siguiente codificación: FI: Empresa Filial CO: Empresa Coligada NA: Empresa que no es Filial o Coligada"],["participacion_porcentual","DOUBLE","","PARTICIPACIÓN_PORC_ENTUAL","a2","ambos","Corresponde señalar el porcentaje de participación de la compañía en la sociedad filial a la fecha de cierre del mes al que se refiere la información"],["patrimonio_filial_m_clp","BIGINT","miles de pesos","PATRIMONIO_FILIAL","a2","ambos","Corresponde informar el patrimonio contable de la filial a la fecha de cierre de los estados financieros para los meses de marzo, junio, septiembre y diciembre. Para los otros períodos, se debe informar el patrimonio contable de la filial del trimestre anterior al período informado. Esta información deberá expresarse en miles de pesos (M$)"],["resultado_de_la_sociedad_filial_m_clp","BIGINT","miles de pesos","RESULTADO_DE_LA_S_OCIEDAD_FILIAL","a2","ambos","Corresponde al resultado (utilidad o pérdida) contable de la filial a la fecha de cierre de los estados financieros para los meses de marzo, junio, septiembre y diciembre. Para los otros períodos se debe informar el resultado contable de la filial del trimestre anterior al período informado. Esta información deberá expresarse en miles de pesos (M$)"],["clasificacion_de_riesgo","VARCHAR","","CLASIFICACION_DE_RIESGO","a2","ambos","Se deberá informar la menor clasificación de riesgo vigente del instrumento a la fecha de cierre del mes a que se refiere la información. Si el instrumento no contara con clasificación de riesgo se debe informar S/C"],["simultanea","VARCHAR","","SIMULTANEA","a2","ambos","Corresponde informar si una o más acciones registradas forman parte de una operación simultánea de acciones. Se informará de acuerdo a la siguiente codificación: CVS : acción afecta a operación simultánea. NVS : acción no afecta a operación simultánea"],["tsa","VARCHAR","","TSA","a2","ambos","Corresponde informar si el instrumento está incluido en el Test de Suficiencia de Activos para el periodo informado, de acuerdo a la siguiente codificación: SI: el instrumento es utilizado para el análisis del Test de Suficiencia de Activos NO: el instrumento no es utilizado para el análisis del Test de Suficiencia de Activos. En periodos que no corresponde enviar el Test de Suficiencia de Activos"],["cobertura","VARCHAR","","COBERTURA","a2","ambos","Corresponde indicar si el instrumento está cubierto por un Derivado y qué tipo de operación de acuerdo a la siguiente Codificación En el primer carácter de este campo se debe indicar: S, si el instrumento está cubierto por un Derivado N, si el instrumento no está cubierto En los caracteres 2 al 5 deberá indicar el código de operación de Derivado de acuerdo a la Codificación de Instrumentos vigente en el sitio web de la SVS Por ejemplo, si el instrumento está cubierto por un swap se debe ingresar: SS si el instrumento está cubierto por un forward de venta se debe ingresar: SFWV Si el instrumento está cubierto por más de una operación de derivado se debe informar SMIX"],["metod_clasif_valo","VARCHAR","","METOD_CLASIF_VALO","a2","ambos","Corresponde informar la clasificación dada al instrumento en los"],["criterio_valorizaci","VARCHAR","","CRITERIO_VALORIZACI","a2","ambos","Corresponde indicar si la inversión está valorizada a Valor"],["modelo_valoracion","VARCHAR","","MODELO_VALORACION","a2","ambos","Corresponde indicar si la inversión está valorizada por la Compañía utilizando un Modelo Propio de valorización de acuerdo a la siguiente codificación: SI : Utiliza Modelo Propio. NO: No utiliza Modelo Propio"],["modelo_propio_deterioro","VARCHAR","","MODELO_PROPIO_DE_TERIORO","a2","ambos","Corresponde indicar si el Deterioro de la inversión se determinó usando una metodología propia o es una aplicación de la metodología definida en la NCG N° 311. Se informará de acuerdo a la siguiente codificación: SI : Método propio para estimar el deterioro. NO : Aplicación de la NCG N°311"],["tipo_fondo","VARCHAR","","TIPO_FONDO","a2","ambos","Para los fondos de inversiones corresponde informar el tipo de fondo según la siguiente clasificación: IN : Inmobiliario. CR : Capital de Riesgo. IE : Infraestructura OT : Otros. Para las acciones se deberá informar: AC"],["rut_fondo_p","VARCHAR","","RUT_FONDO_P","a2","desde 2024-12","Para instrumentos de tipo CFIP y CFIPOIND, se debe informar el 31 Para instrumentos distintos a CFIP y CFIPOIND, se debe completar este campo con ceros"],["nombre_fondo_p","VARCHAR","","NOMBRE_FONDO_P","a2","desde 2024-12","Para instrumentos de tipo CFIP y CFIPOIND, se debe informar el nombre del Fondo al cual pertenece. Para instrumentos distintos a CFIP y CFIPOIND, se debe informar “NO APLICA”"],["codigo_actividad_economica","BIGINT","","CÓDIGO_ACTIVIDAD_E_CONOMICA","a2","desde 2024-12","Se deberá informar para todos los instrumentos (acciones), la codificación designada por el Servicio Impuestos Internos para la actividad económica principal del emisor. Para fondos, se informará con ceros (0)"],["efecto_patrimonio","VARCHAR","","EFECTO_PATRIMONIO","a2","desde 2024-12","Corresponde informar si una inversión, es valorizada a Valor razonable (VR) con cambios en otro resultado integral: SI: Con cambios en otro resultado integral. NO: Sin cambios en otro resultado integral"],["subyacente","VARCHAR","","SUBYACENTE","a2","desde 2024-12","Corresponde informar los activos subyacentes de los fondos de inversión. Solo se informarán los tipos de activos cuya participación en la cartera de inversiones del fondo sea superior o igual al 10%. Se debe informar la combinación de caracteres según el siguiente listado, seleccionando la o las letras correspondientes al tipo de activo, con un máximo de 10 y un mínimo de 1. En caso de sobrar caracteres, deberá rellenarse con espacios. D: Depósitos. I: Instrumentos emitidos por Estados o Bancos Centrales. B: Bonos emitidos por empresas o bancos. P: Pagarés. M: Mutuos hipotecarios. H: Letras hipotecarias. L: Leasings. A: Acciones"],["segmento_fondo","VARCHAR","","SEGMENTO_FONDO","a2","desde 2024-12","Para los fondos de inversiones corresponde informar el segmento del fondo según la siguiente clasificación: 01: Accionarios; Fondos cuyas inversiones en al menos un 70% sean acciones de sociedades anónimas abiertas nacionales o extranjeras. 02: Capital Privado; Fondos cuyas inversiones en al menos un 70% sean acciones de empresas cerradas nacionales o extranjeras. 03: Deuda; Fondos cuyas inversiones en al menos un 70% correspondan a instrumentos de deuda nacionales o extranjeros transados en bolsa. 04: Deuda Privada; Fondos cuyas inversiones en al menos un 70% sean en instrumentos de deuda que no se transan en mercados públicos, y que no estén ligados al sector inmobiliario ni de obras de infraestructura. En esta categoría, por ejemplo, se"],["tipo_inmobiliario","VARCHAR","","TIPO_INMOBILIARIO","a2","desde 2024-12","Corresponde informar, para inversiones en fondos con riesgo subyacente de tipo inmobiliario, el tipo de inversión inmobiliaria según la siguiente clasificación: 01: Renta Habitacional (Residencial): Corresponden a aquellos fondos que tienen por objetivo principal invertir en bienes raíces habitacionales, con el fin de darlos en arriendo. 02: Renta No Habitacional: Corresponden a aquellos fondos que tienen como objetivo principal invertir en todo tipo de negocios inmobiliarios destinados a la renta no residencial. 03: Renta Mixta: Corresponden a aquellos fondos que tienen como objetivo principal invertir en alguna combinación de los números 1) y 2) anteriores. 04: Desarrollo Residencial: Corresponden a aquellos fondos cuyo objetivo principal sea invertir en el desarrollo de bienes raíces para la renta"],["cuotas_suscritas","BIGINT","","CUOTAS_SUSCRITAS","a2","desde 2024-12","Para los fondos de inversiones corresponde informar el número de cuotas suscritas y pagadas del fondo de inversión. Para acciones, se deberá completar con ceros"],["porcentaje_participacion","DOUBLE","","PORCENTAJE_PARTICI_PACION","a2","desde 2024-12","Corresponde Informar el porcentaje de participación de la compañía respecto a las cuotas suscritas y pagadas del fondo de inversión. Para acciones, se deberá completar con ceros"],["desarrollo_avance","VARCHAR","","DESARROLLO_AVANC","a2","desde 2024-12","Para el caso de TIPO_INMOBILIARIO 04, 05, 06 y 07, se debe"],["tipo_gestion","VARCHAR","","TIPO_GESTIÓN","a2","desde 2024-12","Para el caso de TIPO_INMOBILIARIO 04, 05, 06 y 07, se debe indicar el tipo de gestión, de acuerdo a lo siguiente: A: Compañía es responsable de gestionar el proyecto y contrata directamente a una constructora para su desarrollo. B: Compañía es responsable de gestionar el proyecto, no obstante, contrata a un tercero (gestor inmobiliario) en el que delega la gestión del desarrollo. C: La gestión del proyecto la realiza un tercero y la compañía es un aportante (FI) o accionista (ACCR). D: Otro. Para el caso TIPO_INMOBILIARIO 01, 02, 03 y 08 completar con ceros"]]},"bienes_raices":{"cabecera":["columna","tipo","unidad","nombre en la ficha CMF","registro","vigencia","descripción"],"filas":[["periodo","VARCHAR","","","","ambos","Mes de la cartera informada (AAAA-MM)."],["sector","VARCHAR","","","","ambos","vida (archivos CSVID) o generales (CSGEN)."],["rut_aseguradora","VARCHAR","","","","ambos","RUT de la compañía de seguros, con dígito verificador (une con seguros.lista_entidades)."],["nombre_aseguradora","VARCHAR","","","","ambos","Nombre de la compañía tal como aparece en el encabezado del archivo del mes."],["rol","VARCHAR","","ROL","b2","ambos","Corresponde señalar el número bajo el cual se encuentra identificado el bien raíz en el Servicio de Impuestos Internos. En caso que se trate de un contrato de leasing, que esté compuesto por más de un bien inmueble, por ejemplo: una oficina, un estacionamiento y una bodega, los cuales tengan roles diferentes, se informará como único rol uno de éstos, que la compañía estime conveniente. Siempre deberá informarse el mismo rol"],["descripcion_del_inmueble_local","VARCHAR","","DESCRIPCION_DEL_INMUEBLE_Local","b2","ambos","Se indicará si es un local. S : Si N : No"],["descripcion_del_inmueble_oficina","VARCHAR","","DESCRIPCION_DEL_INMUEBLE_Oficina","b2","ambos","Se indicará si es una oficina. S : Si N : No"],["descripcion_del_inmueble_bodega","VARCHAR","","DESCRIPCION_DEL_INMUEBLE_Bodega","b2","ambos","Se indicará si es una bodega. S : Si N : No"],["descripcion_del_inmueble_estacionamiento","VARCHAR","","DESCRIPCION_DEL_INMUEBLE_Estacionamiento","b2","ambos","Se indicará si es un estacionamiento. S : Si N : No"],["descripcion_del_inmueble_terreno","VARCHAR","","DESCRIPCION_DEL_INMUEBLE_Terreno","b2","ambos","Se indicará si es un terreno. S : Si N : No"],["descripcion_del_inmueble_casa","VARCHAR","","DESCRIPCION_DEL_INMUEBLE_Casa","b2","ambos","Se indicará si es una casa. S : Si N : No"],["descripcion_del_inmueble_edificio","VARCHAR","","DESCRIPCION_DEL_INMUEBLE_Edificio","b2","ambos","Se indicará si es un edificio. S : Si N : No"],["descripcion_del_inmueble_piso_completo_de_edificio","VARCHAR","","DESCRIPCION_DEL_INMUEBLE_Piso completo de edificio","b2","ambos","Se indicará si es un piso completo del edificio. S : Si N : No"],["descripcion_del_inmueble_piso_incompleto_de_edificio","VARCHAR","","DESCRIPCION_DEL_INMUEBLE_Piso incompleto de edificio","b2","ambos","Se indicará si es un piso incompleto del edificio. S : Si N : No"],["descripcion_del_inmueble_departamento","VARCHAR","","DESCRIPCION_DEL_INMUEBLE_Departamento","b2","ambos","Se indicará si es un departamento. S : Si N : No"],["descripcion_del_inmueble_obra_en_construccion","VARCHAR","","DESCRIPCION_DEL_INMUEBLE_Obra en construcción","b2","ambos","Se indicará si es una obra en construcción. S : Si N : No"],["descripcion_del_inmueble_otros","VARCHAR","","DESCRIPCION_DEL_INMUEBLE_Otros","b2","ambos","Se indicará si es otros. S : Si N : No Ejemplos: 1. Si el bien raíz es una casa, se informará con una S en el campo CASA, y todos los otros campos deberán informarse con una N. 1. En caso que la compañía tenga contabilizado un local, una oficina y una bodega con un mismo rol, se deberá informar de la siguiente manera: Local : S Oficina : S Bodega : S Estacionamiento : N Terreno : N"],["tipo_de_inmueble","VARCHAR","","TIPO_DE_INMUEBLE","b2","ambos","Corresponde señalar si el bien raíz es urbano o no urbano. Se informará de acuerdo a la siguiente codificación: UR : Urbano NU : No Urbano"],["destino","VARCHAR","","DESTINO","b2","ambos","Corresponde indicar si el bien raíz es \"Habitacional\" o \"No Habitacional\", de acuerdo a las correspondientes autorizaciones municipales. Se informará de acuerdo a la siguiente codificación: HA : Habitacional NH : No Habitacional"],["uso","VARCHAR","","USO","b2","ambos","Corresponde indicar el uso que se le da al bien raíz, es decir si se arrienda con el fin de obtener una renta o es ocupado para desarrollar la actividad de seguros. En caso que una compañía tenga un bien raíz y una parte esté dada en arriendo y otra para uso propio y contablemente esté registrado como un sólo bien, se deberá informar como uso mixto. Se informará de acuerdo a la codificación definida en SEIL, codificación SVS, Circular 1835, Uso bien raíz"],["porcentaje_uso_propio","DOUBLE","","PORCENTAJE_USO_PROPIO","b2","ambos","Corresponde informar, cuando el uso es mixto, qué porcentaje del bien raíz está destinado para uso propio"],["tipo_instrumento","VARCHAR","","TIPO_INSTRUMENTO","b2","ambos","Este campo es obligatorio y se informará de acuerdo a la codificación definida en SEIL, Codificación S.V.S., Instrumentos. Para los bienes raíces dados en leasing, el tipo de instrumento será CLEAS"],["codigo_nemotecnico","VARCHAR","","CODIGO_NEMOTECNICO","b2","ambos","Corresponde informar, cuando sea un bien raíz dado en leasing, el código asignado por esta Superintendencia, según lo señalado en Anexo Nº1 de esta Circular, si no corresponde, se informará con espacios"],["arrendatario","VARCHAR","","ARRENDATARIO","b2","ambos","Corresponde informar la razón social o el nombre del arrendatario de la forma: apellido paterno, apellido materno y primer nombre. Se informará para los bienes raíces dado en arrendamiento, ya sea como leasing financiero u operacional o simple arrendamiento. Si no corresponde, se informará con espacios"],["relacionado","VARCHAR","","RELACIONADO","b2","ambos","En el caso que el bien raíz se encuentre arrendado, corresponde informar si el arrendatario está relacionado con la compañía de seguros, de acuerdo a lo establecido en el artículo N°100 de la ley N°18.045 del 22.10.1981 y sus modificaciones. Se señalará de acuerdo a la siguiente codificación: RE : Relacionado NR : No Relacionado NA : No Aplica"],["saldo_plazo_arriendo","BIGINT","","SALDO_PLAZO_ARRIENDO","b2","ambos","Se deberá informar los meses restantes del contrato de arriendo a contar de la fecha de información. En el caso de los contratos de leasing, se debe indicar el plazo informado en el archivo B.1. En el caso de los bienes raíces de uso propio se debe informar en cero (0)"],["monto_arriendo_uf","DOUBLE","UF","MONTO_ARRIENDO","b2","ambos","Para los bienes raíces en arriendo, corresponde informar el monto de arriendo mensual expresado en UF. En caso de arriendos trimestrales, semestrales, anuales u otros deberán informarse el valor equivalente mensual de éstos. En el caso de los bienes raíces de uso propio y de los leasing se debe informar en cero (0)"],["ubicacion","VARCHAR","","UBICACIÓN","b2","ambos","Corresponderá señalar la dirección exacta del bien raíz"],["comuna","VARCHAR","","COMUNA","b2","ambos","Corresponde señalar la comuna donde se ubica geográficamente el bien raíz, de acuerdo a listado de códigos establecidos en el módulo SEIL, codificación SVS, Comuna"],["ciudad","VARCHAR","","CIUDAD","b2","ambos","Corresponderá señalar la ciudad en donde se encuentra el bien raíz"],["fecha_de_compra","VARCHAR","","FECHA_DE_COMPRA","b2","ambos","Corresponderá señalar la fecha de adquisición del bien raíz. Se deberá informar con el siguiente formato: AAAAMMDD"],["compra_entidad_relacionada","VARCHAR","","COMPRA_ENTIDAD_RELACIONADA","b2","ambos","Corresponde informar si el bien raíz fue adquirido a una entidad relacionada con la compañía de seguros, de acuerdo a lo establecido en las letras a) y b) del artículo N°100 de la ley N°18.045 de 22.10.1981. Se señalará de acuerdo a la siguiente codificación: S : Adquirido a Entidad Relacionada N : No Adquirido a Entidad Relacionada"],["costo_actualizado_m_clp","BIGINT","miles de pesos","COSTO_ACTUALIZADO","b2","ambos","Corresponde señalar el valor de adquisición del bien raíz más su correspondiente revalorización a la fecha de cierre del mes a que se refiere la información, en miles de pesos (M$)"],["depreciacion_acumulada_m_clp","BIGINT","miles de pesos","DEPRECIACION_ACUMULADA","b2","ambos","Corresponde señalar el monto de depreciación acumulada a deducir del activo inmovilizado, en miles de pesos (M$)"],["plazo","BIGINT","","PLAZO","b2","ambos","Se deberá informar los meses de vida útil restante del bien raíz"],["costo_corregido_y_depreciado_m_clp","BIGINT","miles de pesos","COSTO_CORREGIDO_Y_DEPRECIADO","b2","ambos","Corresponde a la diferencia entre el costo actualizado del bien raíz y la depreciación acumulada, en miles de pesos (M$). Para el caso de los bienes raíces entregados en leasing este valor debe incorporar el crédito a que se refiere el párrafo segundo del número 2 del título V de la Circular N° 1360, sobre valorización de inversiones"],["tasacion_1_m_clp","BIGINT","miles de pesos","TASACION_1","b2","ambos","Corresponde señalar el valor según lo dispuesto en Norma de Carácter General Nº42 de esta Superintendencia o la que la reemplace; deberá expresarse en miles de pesos (M$), según la conversión a la fecha de cierre del mes a que se refiere la información, del valor de tasación expresado originalmente en UF"],["tasacion_2_m_clp","BIGINT","miles de pesos","TASACION_2","b2","ambos","Corresponde señalar el valor según lo dispuesto en Norma de Carácter General Nº42 de esta Superintendencia o la que la reemplace; deberá expresarse en miles de pesos (M$), según la conversión a la fecha de cierre del mes a que se refiere la información, del valor de tasación expresado originalmente en UF"],["nombre_del_tasador_1","VARCHAR","","NOMBRE_DEL_TASADOR_1","b2","ambos","Corresponde indicar la razón social o el nombre del profesional que emitió el informe de tasación 1. En este último caso, se indicará: apellido paterno, apellido materno y primer nombre"],["nombre_del_tasador_2","VARCHAR","","NOMBRE_DEL_TASADOR_2","b2","ambos","Corresponde indicar la razón social o el nombre del profesional que emitió el informe de tasación 2. En este último caso, se indicará: apellido paterno, apellido materno, y primer nombre"],["fecha_tasacion_1","VARCHAR","","FECHA_TASACION_1","b2","ambos","Corresponderá señalar la fecha en que se efectuó la tasación 1. Se deberá informar con el siguiente formato: AAAAMMDD"],["fecha_tasacion_2","VARCHAR","","FECHA_TASACION_2","b2","ambos","Corresponderá señalar la fecha en que se efectuó la tasación 2. Se deberá informar con el siguiente formato: AAAAMMDD"],["deterioro_m_clp","BIGINT","miles de pesos","DETERIORO","b2","ambos","Corresponde al deterioro de la inversión, según lo señalado en la Norma de Carácter General N°311, del 28.06.2011. Este monto deberá expresarse en miles de pesos (M$)"],["valor_final_m_clp","BIGINT","miles de pesos","VALOR_FINAL","b2","ambos","Corresponde al valor que tiene el bien raíz a la fecha de cierre del mes a que se refiere la información, según lo establecido en Circular de Valorización vigente, expresados en miles de pesos (M$). En el caso de los bienes raíces dados en leasing corresponde al menor entre el valor final del contrato de leasing indicado en el archivo B.1, el campo valor contable de este archivo y la menor tasación del bien raíz"],["copropietaria","DOUBLE","","COPROPIETARIA","b2","ambos","Corresponde informar si la compañía es copropietaria de un bien raíz, si lo fuera, en este campo deberá informar el porcentaje de propiedad de la compañía"],["prohibicion_o_gravamen","VARCHAR","","PROHIBICION_O_GRAVAMEN","b2","ambos","Se deberá informar si los bienes raíces registrados se encuentran afectos a prohibiciones o gravámenes u otros impedimentos señalados en el Art 22 DFL N°251. Se informará de acuerdo a la siguiente codificación: S : Si tiene prohibición N : No tiene prohibición"],["activo_respalda_reserva_valor_de_fondo","VARCHAR","","ACTIVO_RESPALDA_RESERVA_VALOR_DE_FONDO","b2","ambos","Corresponde informar si uno o más títulos (en caso de haber agrupado instrumentos con características idénticas) registrados, se encuentran respaldando la reserva de valor del fondo señalada en el DFL Nº251. Se informará de acuerdo a la valorización que tengan los títulos, según Circular N°1360 y posteriores modificaciones, con un código de cinco letras formado de la siguiente manera: Las tres primeras letras serán: APV : si los instrumentos respaldan la reserva de valor del fondo de seguros con ahorro previsional voluntario, o OTR : si los instrumentos respaldan la reserva de valor del fondo de seguros con ahorro, distinto a los seguros con ahorro previsional voluntario. La cuarta letra será A, B, C o D dependiendo de la forma de constitución de la reserva de descalce a que se refiere el N°4 de la Norma de Carácter General N°132, de 13 de marzo de 2002 y sus posteriores modificaciones. La quinta letra será G si se garantiza la rentabilidad del valor de la"],["nombre_del_fondo","VARCHAR","","NOMBRE_DEL_FONDO","b2","ambos","Para instrumentos que estén asociados a fondos que respalden seguros de vida con cuenta de inversión, se debe informar el nombre del Fondo al cual pertenece. Se entenderá por fondo al tipo de plan o modalidades de inversión convenidos para los seguros con cuentas de inversión. Para instrumentos que no respalden seguros de vida con cuenta de inversión, se debe informar “NO APLICA”"],["nombre_cartera","VARCHAR","","NOMBRE_CARTERA","b2","ambos","Para instrumentos que no respalden seguros de vida con cuenta de inversión, se debe informar la sub cartera que respalda, si corresponde. Para instrumentos que no respalden una sub cartera, se debe informar “NO APLICA”"],["tsa","VARCHAR","","TSA","b2","ambos","Corresponde informar si el instrumento está incluido en el Test de Suficiencia de Activos para el periodo informado, de acuerdo a la siguiente codificación: SI: el instrumento es utilizado para el análisis del Test de Suficiencia de Activos NO: el instrumento no es utilizado para el análisis del Test de Suficiencia de Activos. En periodos que no corresponde enviar el Test de Suficiencia de Activos"],["desarrollo_avance","VARCHAR","","DESARROLLO_AVANC","b2","desde 2024-12","Para el caso de bienes raíces en construcción, se debe indicar el"],["tipo_gestion","VARCHAR","","TIPO_GESTIÓN","b2","desde 2024-12","Para el caso de bienes raíces en construcción, se debe indicar el tipo de gestión, de acuerdo a lo siguiente: A: La compañía es responsable de gestionar el proyecto y contrata directamente a una constructora para su desarrollo. B: La Compañía es responsable de gestionar el proyecto, no obstante, contrata a un tercero (gestor inmobiliario) en el que delega la gestión del desarrollo. C: Otro. En caso de no aplicar, completar con espacios"],["total_m2_terreno","BIGINT","","TOTAL_M2_TERRENO","b2","desde 2024-12","Para todos los bienes raíces informados, se deberá indicar el total de m2 del terreno. Para el caso de departamentos u oficinas en un edificio, se debe informar con ceros"],["total_m2_construccion","BIGINT","","TOTAL_M2_CONSTRU_CCION","b2","desde 2024-12","Corresponde informar el total de m2 construidos del bien raíz"],["valor_tasacion_terreno_m2_uf","DOUBLE","UF","VALOR_TASACION_TE_RRENO_M2","b2","desde 2024-12","Corresponde informar el valor en UF por metro cuadrado del terreno, obtenido a partir de la menor tasación de la propiedad. Si la tasación no presenta separada la valorización del terreno y la construcción, se debe informar con ceros. Para el caso de departamentos u oficinas en un edificio, se debe informar con ceros"],["valor_tasacion_construccion_m2_uf","DOUBLE","UF","VALOR_TASACION_CO_NSTRUCCION_M2","b2","desde 2024-12","Corresponde informar el valor en UF por metro cuadrado de la construcción, obtenido a partir de la menor tasación de la propiedad. Si la tasación no presenta separada la valorización del terreno y la construcción, se debe informar con ceros"]]},"control_inversiones":{"cabecera":["columna","tipo","unidad","nombre en la ficha CMF","registro","vigencia","descripción"],"filas":[["periodo","VARCHAR","","","","ambos","Mes de la cartera informada (AAAA-MM)."],["sector","VARCHAR","","","","ambos","vida (archivos CSVID) o generales (CSGEN)."],["rut_aseguradora","VARCHAR","","","","ambos","RUT de la compañía de seguros, con dígito verificador (une con seguros.lista_entidades)."],["nombre_aseguradora","VARCHAR","","","","ambos","Nombre de la compañía tal como aparece en el encabezado del archivo del mes."],["tipo_de_inversion","VARCHAR","","TIPO_DE_INVERSION","c2","ambos","Corresponderá a la letra con la cual se clasifica la inversión. Se informará de acuerdo a la codificación definida en SEIL, Codificación S.V.S., Tipo de Inversión"],["valor_final_m_clp","BIGINT","miles de pesos","VALOR_FINAL","c2","ambos","Corresponde al valor que tienen los instrumentos a la fecha de cierre del mes a que se refiere la información, según lo establecido en Circular de Valorización de Inversiones vigente. Este monto se deberá expresar en miles de pesos (M$)"],["inversiones_representativas_de_rt_pr_m_clp","BIGINT","miles de pesos","INVERSIONES_REPRESENTATIVAS_D_E_(RT_+_PR)","c2","ambos","Corresponde al valor de las inversiones que la Compañía considera para respaldar reservas técnicas y patrimonio de riesgo, de acuerdo a los límites señalados en el DFL N°251 expresados en miles de pesos (M$). Al respecto, sólo para los derivados pasivos la información debe presentarse con signo negativo"],["inversiones_no_representativas_de_rt_pr_m_clp","BIGINT","miles de pesos","INVERSIONES_NO_REPRESENTATIVAS_D_E_(RT_+_PR)","c2","ambos","Corresponde al valor de las inversiones que la Compañía no considera para respaldar reservas técnicas y patrimonio de riesgo, expresados en miles de pesos (M$). Al respecto, sólo para los derivados pasivos la información debe presentarse con signo negativo"],["total_costo_amortizado_m_clp","BIGINT","miles de pesos","TOTAL_COSTO_AMOR_TIZADO","c2","ambos","Corresponde al valor que tienen los instrumentos a la fecha del cierre del mes a que se refiere la información, y que están clasificados como “CA” (Costo Amortizado) en el campo METOD_CLASIF_VALORIZ_EEFF de los archivos anteriores de esta circular. Este monto deberá expresarse en miles de pesos (M$)"],["total_valor_razonable_m_clp","BIGINT","miles de pesos","TOTAL_VALOR_RAZON_ABLE","c2","ambos","Corresponde al valor que tienen los instrumentos a la fecha del cierre del mes a que se refiere la información, y que están clasificados como “VR” (Valor Razonable) en el campo METOD_CLASIF_VALORIZ_EEFF de los archivos anteriores de esta circular. Este monto deberá expresarse en miles de pesos (M$)"],["total_efectivo_equivalente_m_clp","BIGINT","miles de pesos","TOTAL_EFECTIVO_EQ_UIVALENTE","c2","ambos","Corresponde al valor que tienen los instrumentos a la fecha del cierre del mes a que se refiere la información, y que están clasificados como “EE” (Efectivo Equivalente) en el campo METOD_CLASIF_VALORIZ_EEFF de los archivos anteriores de esta circular. Este monto deberá expresarse en miles de pesos (M$)"],["total_instrumento_s_cui_apv_m_clp","BIGINT","miles de pesos","TOTAL_INSTRUMENTO_S_CUI_APV","c2","ambos","Corresponde al valor que tienen los instrumentos a la fecha del cierre del mes a que se refiere la información, y que NO están clasificados como “VIDA” o “GRAL” en el campo ACTIVO_RESPALDA_RESERVA_VALOR_DEL_FONDO de los archivos anteriores de esta circular. Este monto deberá expresarse en miles de pesos (M$)"],["total_inst_otras_clasif_m_clp","BIGINT","miles de pesos","TOTAL_INST_OTRAS_C_LASIF","c2","ambos","Corresponde al valor que tienen los instrumentos a la fecha del cierre del mes a que se refiere la información, y que están clasificados como “OTRCLA” (Otra Clasificación dentro de los Estados de Situación Financiera) en el campo METOD_CLASIF_VALORIZ_EEFF de los archivos anteriores de esta circular. Este monto deberá expresarse en miles de pesos (M$)"],["total_soc_filiales_m_clp","BIGINT","miles de pesos","TOTAL_SOC_FILIALES","c2","ambos","Corresponde informar el monto que tiene invertido a la fecha del cierre del mes a que se refiere la información y que corresponde a las Participaciones y Acciones en Sociedades Filiales. Adicionalmente, se deberá incluir en este campo el monto final invertido en acciones de Sociedades Filiales. Este monto deberá expresarse en miles de pesos (M$)"],["total_coligadas_m_clp","BIGINT","miles de pesos","TOTAL_COLIGADAS","c2","ambos","Corresponde informar el monto que tiene invertido a la fecha del cierre del mes a que se refiere la información y que corresponde a las Participaciones y Acciones en Sociedades Coligadas. Adicionalmente, se deberá incluir en este campo el monto final invertido en acciones de Sociedades Coligadas. Este monto deberá expresarse en miles de pesos (M$)"]]},"fondos_mutuos":{"cabecera":["columna","tipo","unidad","nombre en la ficha CMF","registro","vigencia","descripción"],"filas":[["periodo","VARCHAR","","","","ambos","Mes de la cartera informada (AAAA-MM)."],["sector","VARCHAR","","","","ambos","vida (archivos CSVID) o generales (CSGEN)."],["rut_aseguradora","VARCHAR","","","","ambos","RUT de la compañía de seguros, con dígito verificador (une con seguros.lista_entidades)."],["nombre_aseguradora","VARCHAR","","","","ambos","Nombre de la compañía tal como aparece en el encabezado del archivo del mes."],["rut_administradora","VARCHAR","","RUT_ADMINISTRADORA","f2","ambos","Se deberá informar el RUT de la administradora del fondo"],["run","VARCHAR","","RUN","f2","ambos","Corresponde informar el RUN de cada fondo que forma parte de las inversiones de la compañía de acuerdo a codificación definida en SEIL, Codificación S.V.S., Fondos Mutuos"],["tipo_instrumento","VARCHAR","","TIPO_INSTRUMENTO","f2","ambos","Este campo es obligatorio y se informará de acuerdo a la codificación definida en SEIL, Codificación S.V.S., Instrumentos"],["nemotecnico","VARCHAR","","NEMOTECNICO","f2","ambos","Corresponde informar el código nemotécnico de acuerdo a las instrucciones impartidas por Circular N° 1085 o la que la reemplace"],["tipo_fondo","VARCHAR","","TIPO_FONDO","f2","ambos","Se debe informar el tipo de fondo según la siguiente clasificación: IN : Inmobiliario. CA : Capital de Riesgo. IE : Infraestructura OT : Otros"],["serie","VARCHAR","","SERIE","f2","ambos","Se debe informar la serie del fondo mutuo. Si el fondo mutuo posee una serie única de cuotas se debe informar UNICA"],["unidades","DOUBLE","","UNIDADES","f2","ambos","Corresponde al número de cuotas propiedad de la entidad a la fecha de cierre del mes a que se refiere la información"],["unidad_monetaria","VARCHAR","","UNIDAD_MONETARIA","f2","ambos","Corresponde a la unidad monetaria o moneda en la que se contabiliza el fondo. Se informará de acuerdo a la codificación definida en SEIL, codificación S.V.S., Unidades Monetarias"],["valor_cuota_clp","DOUBLE","pesos","VALOR_CUOTA","f2","ambos","Corresponde al valor de rescate de la cuota a la fecha de cierre del mes a que se refiere la información, expresados en pesos ($)"],["valor_de_inversion_clp","BIGINT","pesos","VALOR_DE_INVERSION","f2","ambos","Corresponde al valor pagado por las cuotas, más las comisiones e impuestos (exceptos aquellos recuperables) contabilizado a la fecha de cierre del mes a que se refiere la información, expresado en pesos ($)"],["valor_razonable_clp","BIGINT","pesos","VALOR_RAZONABLE","f2","ambos","Corresponde al producto del número de unidades por el valor de la cuota a la fecha de cierre del mes a que se refiere la información, en pesos ($)"],["deterioro_clp","BIGINT","pesos","DETERIORO","f2","ambos","Corresponde al deterioro de la inversión, según lo señalado en la Norma de Carácter General N°311, del 28.06.2011. Este monto deberá expresarse en pesos ($)”"],["valor_final_m_clp","BIGINT","miles de pesos","VALOR_FINAL","f2","ambos","Corresponde al valor que tiene el instrumento a la fecha de cierre del mes a que se refiere la información, según lo establecido en Circular de Valorización de Inversiones vigente. Este monto se deberá expresar en miles de pesos (M$)"],["prohibicion_o_gravamen","VARCHAR","","PROHIBICION_O_GRAVAMEN","f2","ambos","Se deberá informar si las cuotas de fondos mutuos registrados se encuentran afectos a prohibición o gravamen. Se informará de acuerdo a la siguiente codificación: S : Si tiene prohibición N : No tiene prohibición"],["activo_en_margen","VARCHAR","","ACTIVO_EN_MARGEN","f2","ambos","Corresponde informar si uno o más títulos registrados (en caso de haber agrupado instrumentos con características idénticas) se encuentran otorgados como margen de las operaciones de derivado señaladas en el DFL Nº251. Cuando el instrumento se encuentre en margen, se informará el tipo de contrato al cual está asociado utilizando la codificación definida en el SEIL, Codificación S.V.S., Instrumentos Derivados y Pactos. Si no está en margen se informará N"],["unidades_en_margen","DOUBLE","","UNIDADES_EN_MARGEN","f2","ambos","Corresponde informar el número de cuotas de fondos que se encuentran otorgados como margen de las operaciones de derivados señaladas en el DFL Nº251"],["activo_respalda_reserva_valor_de_fondo","VARCHAR","","ACTIVO_RESPALDA_RESERVA_VALOR_DE_FONDO","f2","ambos","Corresponde informar si uno o más títulos (en caso de haber agrupado instrumentos con características idénticas) registrados, se encuentran respaldando la reserva de valor del fondo señalada en el DFL Nº251. Se informará de acuerdo a la valorización que tengan los títulos, según Circular N°1360 y posteriores modificaciones, con un código de cinco letras formado de la siguiente manera: Las tres primeras letras serán: APV : si los instrumentos respaldan la reserva de valor del fondo de seguros con ahorro previsional voluntario, o OTR : si los instrumentos respaldan la reserva de valor del fondo de seguros con ahorro, distinto a los seguros con ahorro previsional voluntario. La cuarta letra será A, B, C o D dependiendo de la forma de constitución de la reserva de descalce a que se refiere el N°4 de la Norma de Carácter General N°132, de 13 de marzo de 2002 y sus posteriores modificaciones. La quinta letra será:"],["nombre_del_fondo","VARCHAR","","NOMBRE_DEL_FONDO","f2","ambos","Para instrumentos que estén asociados a fondos que respalden seguros de vida con cuenta de inversión, se debe informar el nombre del Fondo al cual pertenece. Se entenderá por fondo al tipo de plan o modalidades de inversión convenidos para los seguros con cuentas de inversión. Para instrumentos que no respalden seguros de vida con cuenta de inversión, se debe informar “NO APLICA”"],["nombre_cartera","VARCHAR","","NOMBRE_CARTERA","f2","ambos","Para instrumentos que no respalden seguros de vida con cuenta de inversión, se debe informar la sub cartera que respalda, si corresponde. Para instrumentos que no respalden una sub cartera, se debe informar “NO APLICA”"],["custodia_inv","VARCHAR","","CUSTODIA_INV","f2","ambos","Corresponde informar para cada instrumento, el tipo de custodia que presenta, de acuerdo a la siguiente codificación: CIA: Custodia en Compañía. DCV: Custodia en DCV, solo si la Cía. actuó como Depositante. EXT: Custodia en Otra entidad"],["nombre_custodio","VARCHAR","","NOMBRE_CUSTODIO","f2","ambos","Corresponde informar el nombre de la entidad que custodia la inversión en el evento que se informe en el campo CUSTODIA_INV, el código EXT (otra entidad de custodia). En caso de que no corresponda informar, se deberá llenar con espacios este campo"],["susceptibles_de_custodia","VARCHAR","","SUSCEPTIBLES_DE_CUSTODIA","f2","ambos","Se deberá informar si el instrumento es susceptible de ser custodiado de acuerdo a lo dispuesto en Circular N° 88 del Depósito Central de Valores S.A., y sus modificaciones posteriores, de acuerdo a la siguiente codificación: S: es susceptible de ser custodiado. N: no es susceptible de ser custodiado"],["relacionado","VARCHAR","","RELACIONADO","f2","ambos","Corresponde informar si el emisor del instrumento está relacionado con la compañía de seguros, de acuerdo a lo establecido en el artículo N°100 de la ley N°18.045 del 22.10.1981 y sus modificaciones. Se señalará de acuerdo a la siguiente codificación: RE : Relacionado NR : No Relacionado"],["clasificacion_de_riesgo","VARCHAR","","CLASIFICACION_DE_RIESGO","f2","ambos","Se deberá informar la menor clasificación de riesgo vigente del instrumento a la fecha de cierre del mes a que se refiere la información. Si el instrumento no contara con clasificación de riesgo se debe informar S/C"],["tsa","VARCHAR","","TSA","f2","ambos","Corresponde informar si el instrumento está incluido en el Test de Suficiencia de Activos para el periodo informado, de acuerdo a la siguiente codificación: SI: el instrumento es utilizado para el análisis del Test de Suficiencia de Activos NO: el instrumento no es utilizado para el análisis del Test de Suficiencia de Activos. En periodos que no corresponde enviar el Test de Suficiencia de Activos"],["cobertura","VARCHAR","","COBERTURA","f2","ambos","Corresponde indicar si el instrumento está cubierto por un Derivado y qué tipo de operación de acuerdo a la siguiente Codificación En el primer carácter de este campo se debe indicar: S, si el instrumento está cubierto por un Derivado N, si el instrumento no está cubierto En los caracteres 2 al 5 deberá indicar el código de operación de Derivado de acuerdo a la Codificación de Instrumentos vigente en el sitio web de la SVS Por ejemplo, si el instrumento está cubierto por un swap se debe ingresar: SS si el instrumento está cubierto por un forward de venta se debe ingresar: SFWV Si el instrumento está cubierto por más de una operación de derivado se debe informar SMIX"],["metod_clasif_valo","VARCHAR","","METOD_CLASIF_VALO","f2","ambos","Corresponde informar la clasificación dada al instrumento en los"],["criterio_valorizaci","VARCHAR","","CRITERIO_VALORIZACI","f2","ambos","Corresponde indicar si la inversión está valorizada a Valor"],["modelo_valoracion","VARCHAR","","MODELO_VALORACION","f2","ambos","Corresponde indicar si la inversión está valorizada por la Compañía utilizando un Modelo Propio de valorización de acuerdo a la siguiente codificación: SI : Utiliza Modelo Propio. NO: No utiliza Modelo Propio"],["modelo_propio_deterioro","VARCHAR","","MODELO_PROPIO_DET_ERIORO","f2","ambos","Corresponde indicar si el Deterioro de la inversión se determinó usando una metodología propia o es una aplicación de la metodología definida en la NCG N° 311. Se informará de acuerdo a la siguiente codificación: SI : Método propio para estimar el deterioro. NO : Aplicación de la NCG N°311"],["simultanea","VARCHAR","","SIMULTANEA","f2","desde 2024-12","Corresponde informar si una o más cuotas de fondos registradas forman parte de una operación simultánea. Se informará de acuerdo a la siguiente codificación: CVS : Cuota de fondo afecta a operación simultánea. NVS : Cuota de fondo no afecta a operación simultánea"]]},"renta_fija":{"cabecera":["columna","tipo","unidad","nombre en la ficha CMF","registro","vigencia","descripción"],"filas":[["periodo","VARCHAR","","","","ambos","Mes de la cartera informada (AAAA-MM)."],["sector","VARCHAR","","","","ambos","vida (archivos CSVID) o generales (CSGEN)."],["rut_aseguradora","VARCHAR","","","","ambos","RUT de la compañía de seguros, con dígito verificador (une con seguros.lista_entidades)."],["nombre_aseguradora","VARCHAR","","","","ambos","Nombre de la compañía tal como aparece en el encabezado del archivo del mes."],["codigo_operacion","VARCHAR","","CODIGO_OPERACIÓN","i2","ambos","Código que identifica la operación. Se informará de acuerdo a la siguiente codificación: CDT : Compra definitiva o a término. CRV : Compra con compromiso de retroventa"],["folio_operacion","BIGINT","","FOLIO_OPERACIÓN","i2","ambos","Corresponde al número de la papeleta de la mesa de dinero de la compañía, donde se registra la compra del instrumento. En caso de no poder obtener este número se deberá asociar al documento contable que respalda la compra del instrumento. En el caso del BR, adquirido como parte de una prima, se deberá señalar el RUT sin incluir el dígito verificador de la persona dueña del BR, en caso de repetición, se deberá asignar una secuencia (01, 02, ..., n) en el campo ITEM_OPERACION"],["item_operacion","BIGINT","","ITEM_OPERACION","i2","ambos","Secuencia del instrumento dentro del folio de la operación. No pueden existir dos instrumentos con igual folio e ítem operación"],["fecha_compra","VARCHAR","","FECHA_COMPRA","i2","ambos","Corresponde a la expresión numérica de la fecha en la cual la entidad aseguradora o reaseguradora adquirió el instrumento, emitió o adquirió el leasing o realizó el pacto. Se deberá informar con el siguiente formato: AAAAMMDD"],["fecha_de_pago","VARCHAR","","FECHA_DE_PAGO","i2","ambos","Corresponde a la expresión numérica de la fecha en la cual la entidad aseguradora o reaseguradora realizó la liquidación de la transacción. Se deberá informar con el siguiente formato: AAAAMMDD"],["nro_rut","VARCHAR","","NRO_RUT","i2","ambos","Corresponde informar el RUT del emisor de cada título que forme parte de las inversiones de la compañía. Es obligatorio y no puede informarse en ceros"],["tipo_instrumento","VARCHAR","","TIPO_INSTRUMENTO","i2","ambos","Este campo es obligatorio y se informará de acuerdo a la codificación definida en SEIL, codificación S.V.S., Instrumentos"],["nemotecnico","VARCHAR","","NEMOTECNICO","i2","ambos","Corresponde obligatoriamente informar el código nemotécnico de acuerdo a las instrucciones impartidas por Circular N° 1085 o la que la reemplace. En el caso de los instrumentos no seriados (mutuos hipotecarios, contratos de leasing de bienes raíces y créditos sindicados), se utilizará el código asignado por esta Superintendencia según lo señalado en Anexo Nº 1 de esta Circular. En el caso de instrumentos financieros de renta fija emitidos por empresas nacionales y transados en el extranjero, corresponde informar el código universal “ISIN” (International Securities Identification Number), a falta de éste, el código “CUSIP” (Commitee On Uniform Securities Identification Procedures). De no existir los anteriores, se deberá consultar a esta Superintendencia"],["fecha_emision","VARCHAR","","FECHA_EMISION","i2","ambos","Corresponde a la expresión numérica de la fecha desde la cual se inicia el devengamiento de intereses. En el caso de los Bonos de Reconocimiento corresponde a la expresión numérica de la fecha de afiliación. En el caso de los Mutuos Hipotecarios y Leasing, corresponde a la fecha en que el instrumento fue otorgado al deudor. Se deberá informar con el siguiente formato: AAAAMMDD"],["num_inscripcion","BIGINT","","NUM_INSCRIPCION","i2","ambos","En el caso de instrumentos inscritos en la S.V.S., corresponde informar el número de inscripción del título. En caso contrario, se llenará con ceros"],["fecha_inscripcion","VARCHAR","","FECHA_INSCRIPCION","i2","ambos","Corresponde a la expresión numérica de la fecha de inscripción del instrumento. Se deberá informar con el siguiente formato: AAAAMMDD. Si no corresponde informar, se llenará con ceros"],["serie","VARCHAR","","SERIE","i2","ambos","Corresponde informar la serie de cada instrumento cuando corresponda. En el caso de los instrumentos no seriados se deberá llenar con espacios"],["pais","VARCHAR","","PAIS","i2","ambos","Corresponde informar el país donde se realizó la transacción del instrumento. Se informará de acuerdo a la codificación definida en el SEIL, Codificación S.V.S., Países. Si no corresponde informar, se llenará con espacios"],["valor_nominal","DOUBLE","","VALOR_NOMINAL","i2","ambos","Corresponde informar el valor nominal del instrumento a la fecha de cierre del mes a que se refiere la información. Es decir, los nominales comprados originalmente menos las ventas realizadas sobre el mismo título. No se deberán rebajar las amortizaciones del instrumento a la fecha de valorización. Cabe señalar que cuando se hayan agrupado títulos con idénticas características en un folio de operación, corresponderá informar en este campo la suma de sus respectivos valores nominales, debiéndose anotar el monto exacto hasta con 4 decimales"],["valor_nominal_vigente","DOUBLE","","VALOR_NOMINAL_VIGENTE","i2","ambos","Corresponde informar el valor nominal vigente del instrumento a la fecha de cierre del mes a que se refiere la información. Se deberán rebajar las amortizaciones del instrumento a la fecha de valorización. Cabe señalar que cuando se hayan agrupado títulos con idénticas características en un folio de operación, corresponderá informar en este campo la suma de sus respectivos valores nominales vigentes, debiéndose anotar el monto exacto hasta con 4 decimales. Este campo debe informarse sólo para los instrumentos tipo BE, EC y BS, para los demás instrumentos deberá llenarse con ceros"],["unidad_monetaria","VARCHAR","","UNIDAD_MONETARIA","i2","ambos","Corresponde informar la unidad monetaria o la moneda en la cual está expresado el valor nominal. Se informará de acuerdo a la codificación definida en SEIL, codificación S.V.S., Unidades Monetarias"],["prohibicion","VARCHAR","","PROHIBICION","i2","ambos","Corresponde informar si uno o más títulos (en caso de haber agrupado instrumentos con características idénticas) registrados se encuentran afectos a prohibiciones, gravámenes u otros impedimentos señalados en el DFL Nº 251. Se informará de acuerdo a la siguiente codificación: S : Si tiene prohibición N : No tiene prohibición"],["activo_en_margen","VARCHAR","","ACTIVO_EN_MARGEN","i2","ambos","Corresponde informar si uno o más títulos registrados (en caso de haber agrupado instrumentos con características idénticas) se encuentran otorgados como margen de las operaciones de derivado señaladas en el DFL Nº251. Cuando el instrumento se encuentre en margen, se informará el tipo de contrato al cual está asociado utilizando la codificación definida en el SEIL, Codificación S.V.S., Instrumentos Derivados y Pactos. Si no está en margen se informará N"],["instrumento_vencido","VARCHAR","","INSTRUMENTO_VENCIDO","i2","ambos","Corresponde informar si uno o más títulos (en caso de haber agrupado instrumentos con características idénticas) registrados, se encuentran vencidos a la fecha de cierre del mes a que se refiere la información, y no han sido cobrados; por ej.: BR vencido en proceso de cobranza al INP. Se informará de acuerdo a la siguiente codificación: S : Instrumento se encuentra vencido. N : Instrumento no se encuentra vencido"],["opcion_de_prepago_o_rescate","VARCHAR","","OPCION_DE_PREPAGO_O_RESCATE","i2","ambos","Corresponde informar si tienen opción de prepago. Se informará de acuerdo a la siguiente codificación: S : con opción. N : sin opción"],["fecha_de_prepago","VARCHAR","","FECHA_DE_PREPAGO","i2","ambos","Corresponde a la expresión numérica de la fecha de prepago de los instrumentos, si la tuvieren. Se deberá informar con el siguiente formato: AAAAMMDD Si no corresponde informar, se llenará con ceros"],["activo_respalda_reserva_valor_de_fondo","VARCHAR","","ACTIVO_RESPALDA_RESERVA_VALOR_DE_FONDO","i2","ambos","Corresponde informar si uno o más títulos (en caso de haber agrupado instrumentos con características idénticas) registrados, se encuentran respaldando la reserva de valor del fondo señalada en el DFL Nº251. Se informará de acuerdo a la valorización que tengan los títulos, según Circular N°1360 y posteriores modificaciones, con un código de cinco letras formado de la siguiente manera: Las tres primeras letras serán: APV : si los instrumentos respaldan la reserva de valor del fondo de seguros con ahorro previsional voluntario, o OTR : si los instrumentos respaldan la reserva de valor del fondo de seguros con ahorro, distinto a los seguros con ahorro previsional voluntario La cuarta letra será A, B, C o D dependiendo de la forma de constitución de la reserva de descalce a que se refiere el N°4 de la Norma de Carácter General N°132, de 13 de marzo de 2002 y sus posteriores modificaciones. La quinta letra será G si se garantiza la rentabilidad del valor de la"],["nombre_del_fondo","VARCHAR","","NOMBRE_DEL_FONDO","i2","ambos","Para instrumentos que estén asociados a fondos que respalden seguros de vida con cuenta de inversión, se debe informar el nombre del Fondo al cual pertenece. Se entenderá por fondo al tipo de plan o modalidades de inversión convenidos para los seguros con cuentas de inversión. Para instrumentos que no respalden seguros de vida con cuenta de inversión, se debe informar “NO APLICA”"],["nombre_cartera","VARCHAR","","NOMBRE_CARTERA","i2","ambos","Para instrumentos que no respalden seguros de vida con cuenta de inversión, se debe informar la sub cartera que respalda, si corresponde. Para instrumentos que no respalden una sub cartera, se debe informar “NO APLICA”"],["activo_calce","VARCHAR","","ACTIVO_CALCE","i2","ambos","Sólo las compañías de vida deben informar si el instrumento, cumple con los requisitos establecidos en circular N° 1512 y posteriores modificaciones y además si son considerados para los distintos tramos de calce. Se informará de acuerdo con la siguiente codificación: CAA: los flujos del activo cumplen con todos los requisitos para ser considerados en cualquiera de los 10 tramos de calce y se encuentran incluidos en calce. CAB: los flujos del activo no cumplen con alguno de los requisitos establecidos en la circular 1512 para ser incluidos en los tramos 9 y 10 de calce. Pero los flujos del 1 al 8 se encuentran incluidos en calce NAC: los flujos del activo NO se encuentran incluidos en tramos de calce o no es aplicable para la compañía la Circular 1512. Las compañías de generales deberán informar espacios"],["con_descriptor","VARCHAR","","CON_DESCRIPTOR","i2","ambos","Corresponde a si el instrumento tiene o no descriptor y tabla de desarrollo. Se informara de acuerdo a la siguiente codificación: “S”: Tiene descriptor y tabla de desarrollo. “B”: Para Bonos de reconocimiento. “U”. Para instrumentos distintos a los anteriores"],["relacionado","VARCHAR","","RELACIONADO","i2","ambos","Corresponde informar si el emisor del instrumento está relacionado con la compañía de seguros, de acuerdo a lo establecido en el artículo N°100 de la ley N°18.045 del 22.10.1981 y sus modificaciones. Se señalará de acuerdo a la siguiente codificación: RE : Relacionado NR : No Relacionado En el caso de los contratos de leasing y los mutuos hipotecarios se debe informar el campo considerando, si el arrendatario o el deudor del mutuo está relacionado con la compañía de seguros o no"],["clasificacion_de_riesgo","VARCHAR","","CLASIFICACION_DE_RIESGO","i2","ambos","Se deberá informar la menor clasificación de riesgo vigente del instrumento a la fecha de cierre del mes a que se refiere la información. Si el instrumento no contara con clasificación de riesgo se debe informar S/C"],["clasificacion_inversion","VARCHAR","","CLASIFICACION_INVERSION","i2","ambos","Corresponde informar la clasificación asignada a la inversión de renta fija, de acuerdo a la siguiente codificación: D: Disponible para la venta M: Mantenida hasta el vencimiento"],["fecha_vencimiento","VARCHAR","","FECHA_VENCIMIENTO","i2","ambos","Corresponde a la expresión numérica de la fecha en que el instrumento vence, es decir aquella del último cupón o pago único según corresponda. Se deberá informar con el siguiente formato: AAAAMMDD. Este campo debe ser informado para todos los instrumentos de este archivo"],["tasa_emision","DOUBLE","","TASA_EMISION","i2","ambos","Corresponde a la tasa con la cual fue emitido el instrumento y con la cual se construyen los flujos de la tabla de desarrollo. Para el caso de instrumentos de intermediación financiera como por ejemplo: depósitos, pagarés, u otros, se deberá informar la tasa que paga el instrumento"],["tasa_base","VARCHAR","","TASA_BASE","i2","ambos","Corresponde informar la forma de cálculo de intereses del título. Se informará de acuerdo a la codificación definida en SEIL, codificación SVS, Circular 1835, Forma de cálculo de intereses"],["tsa","VARCHAR","","TSA","i2","ambos","Corresponde informar si el instrumento está incluido en el Test de Suficiencia de Activo para el periodo informado, de acuerdo a la siguiente codificación: SI: el instrumento es utilizado para el análisis del Test de Suficiencia de Activos NO: el instrumento no es utilizado para el análisis del Test de Suficiencia de Activos En periodos que no corresponde enviar el Test de Suficiencia de Activos dejar información del último envío"],["cobertura","VARCHAR","","COBERTURA","i2","ambos","Corresponde indicar si el instrumento está cubierto por un Derivado y qué tipo de operación de acuerdo a la siguiente Codificación En el primer carácter de este campo se debe indicar: S, si el instrumento está cubierto por un Derivado N, si el instrumento no está cubierto En los caracteres 2 al 5 deberá indicar el código de operación de Derivado de acuerdo a la Codificación de Instrumentos vigente en el sitio web de la SVS Por ejemplo, si el instrumento está cubierto por un swap se debe ingresar: SS si el instrumento está cubierto por un forward de venta se debe ingresar: SFWV Si el instrumento está cubierto por más de una operación de derivado se debe informar SMIX"],["metod_clasif_valo","VARCHAR","","METOD_CLASIF_VALO","i2","ambos","Corresponde informar la clasificación dada al instrumento en los"],["criterio_valorizaci","VARCHAR","","CRITERIO_VALORIZACI","i2","ambos","Corresponde indicar si la inversión está valorizada a Valor"],["modelo_valoracion","VARCHAR","","MODELO_VALORACION","i2","ambos","Corresponde indicar si la inversión está valorizada por la Compañía utilizando un Modelo Propio de valorización de acuerdo a la siguiente codificación: SI : Utiliza Modelo Propio. NO: No utiliza Modelo Propio"],["modelo_propio_deterioro","VARCHAR","","MODELO_PROPIO_DE_TERIORO","i2","ambos","Corresponde indicar si el Deterioro de la inversión se determinó usando una metodología propia o es una aplicación de la metodología definida en la NCG N° 311. Se informará de acuerdo a la siguiente codificación: SI : Método propio para estimar el deterioro. NO : Aplicación de la NCG N°311"],["codigo_actividad_economica","BIGINT","","CÓDIGO_ACTIVIDAD_E_CONOMICA","i2","ambos","Se deberá informar para todos los instrumentos, la codificación designada por el Servicio Impuestos Internos para la actividad económica principal del emisor. En el caso de los instrumentos cuyos emisores estén listados en una bolsa de valores y los Mutuos Hipotecarios deben ser informados con ceros"],["grupo_economico","BIGINT","","GRUPO_ECONÓMICO","i2","ambos","Se deberá informar el grupo económico al que pertenece el deudor, para los contratos de leasing, créditos sindicados, AFR y para cualquier otro activo expuesto al riesgo de crédito que no sea de oferta pública. En el caso de los Mutuos Hipotecarios, sólo se deberá informar para aquellos con código de FIN1 igual a 20, 21 o 30. Cuando el deudor no pertenezca a uno de los grupos definidos por la SVS se debe informar con ceros"],["fuente_precios","VARCHAR","","FUENTE_PRECIOS","i2","ambos","Corresponde informar el nombre del proveedor del precio utilizado por la compañía para valorizar a valor razonable el instrumento"],["rut_precio","VARCHAR","","RUT_PRECIO","i2","ambos","Corresponde informar el RUT del proveedor de precios utilizado por la compañía para valorizar a valor razonable el instrumento. Para proveedores que no cuenten con RUT, se deberá informar con ceros"],["tipo_nominales","VARCHAR","","TIPO_NOMINALES","i2","ambos","Corresponde a si las unidades nominales están expresadas a fecha de emisión o a fecha de vencimiento. Esto especifica la forma de obtener un valor par o presente (descontando o capitalizando). Se informará de acuerdo a la siguiente codificación: I : a fecha de emisión F : a fecha de vencimiento"],["tratamiento","VARCHAR","","TRATAMIENTO","i2","ambos","Corresponde a la forma de descuento del valor de los flujos futuros (interés más amortización). Se deberá codificar de la siguiente manera: CC : Con cupones. Indica que se trata de un instrumento con flujos de vencimiento regulares. SC : Sin cupones. CV : Cupones variables. Indica que se trata de un instrumento con flujos de vencimientos variables y están especificados por una fecha predefinida pudiendo no ser la misma para cada flujo"],["valor_inicial_m_clp","BIGINT","miles de pesos","VALOR_INICIAL","i2","ambos","En este campo se registrará el monto que resulte menor entre el valor del instrumento subyacente, según circular de valorización vigente y el monto efectivamente pagado de acuerdo al contrato de pacto, expresado en M$. Este valor debe ser igual al valor informado para el activo subyacente a este pacto en el campo VALOR_FINAL del registro 6 del archivo B.1, el cual deberá mantenerse invariable durante el periodo de duración del pacto. Es decir, no se deben incluir los intereses devengados por la operación de pacto ni los intereses ni reajustes correspondientes al activo subyacente"],["valor_pactado","DOUBLE","","VALOR_PACTADO","i2","ambos","Corresponde al valor al vencimiento del pacto, acordado en el contrato de pacto, expresado en la moneda del pacto"],["unidad_monetaria_p","VARCHAR","","UNIDAD_MONETARIA_P","i2","ambos","Corresponde informar la unidad monetaria o moneda en la cual está expresado el pacto. Se informará de acuerdo a la codificación definida en SEIL, codificación S.V.S., Unidades Monetarias"],["fecha_venc_pacto","VARCHAR","","FECHA_VENC_PACTO","i2","ambos","Corresponde informar la fecha de vencimiento del pacto. Se deberá informar con el siguiente formato: AAAAMMDD"],["tasa_pacto","DOUBLE","","TASA_PACTO","i2","ambos","Corresponde informar la tasa a la cual fue realizado el pacto, indicada en el contrato de pacto"],["tasa_base_p","VARCHAR","","TASA_BASE_P","i2","ambos","Corresponde informa la forma de cálculo de intereses del título. Se informará de acuerdo a la codificación definida en SEIL, codificación SVS, Circular 1835, Forma de cálculo de intereses"],["tipo_nominales_p","VARCHAR","","TIPO_NOMINALES_P","i2","ambos","Corresponde a los tipos nominales en que está expresado el pacto: I : a fecha de emisión F : a fecha de vencimiento"],["valor_pacto_m_clp","BIGINT","miles de pesos","VALOR_PACTO","i2","ambos","Corresponde informar el valor en que se encuentra contabilizado el pacto, de acuerdo a las instrucciones de Circular sobre valorización vigente de esta Superintendencia, a la fecha de cierre del mes a que se refiere la información, expresado en M$. Es decir, al monto registrado en el campo VALOR_INICIAL más los intereses devengados del pacto a la fecha de cierre"],["codigo_agente","VARCHAR","","CODIGO_AGENTE","i2","ambos","Corresponde informar el código de la agencia que administra el mutuo hipotecario. Se informará de acuerdo a la codificación definida en SEIL, codificación S.V.S., Agencias Administradoras de Mutuos Hipotecarios. Para el caso de los Leasing, se llenará con espacios"],["fin_1","BIGINT","","FIN_1","i2","ambos","Corresponde indicar la finalidad del mutuo otorgado. Los códigos permitidos son: 10: Bien raíz habitacional - urbano 11: Bien raíz habitacional - no urbano 20: Bien raíz no habitacional - urbano 21: Bien raíz no habitacional - no urbano 30: Fines generales Para el caso de los Leasing, se llenará con ceros"],["fin_2","VARCHAR","","FIN_2","i2","ambos","Se debe indicar para qué será utilizado el crédito. Los códigos permitidos son: A: Adquisición (bien raíz) C: Construcción (bien raíz) R: Reparación o Ampliación (bien raíz) F: Refinanciamiento (bien raíz o fines generales) P: Prepago (bien raíz o fines generales) O: Otro (fines generales) Debe informarse en letra mayúscula Para el caso de los Leasing, se llenará con espacios"],["tipo_deudor","VARCHAR","","TIPO_DEUDOR","i2","ambos","Corresponde indicar si el deudor del mutuo o del leasing es persona natural o jurídica y si es persona relacionada o no a la compañía, de acuerdo a la siguiente codificación: A: persona natural no relacionada B: persona natural relacionada C: persona jurídica no relacionada D: persona jurídica relacionada"],["rut_deudor","VARCHAR","","RUT_DEUDOR","i2","ambos","Se debe informar el Rut del deudor del mutuo hipotecario endosable o del contrato de leasing según sea el caso"],["fecha_primer_dividendo","VARCHAR","","FECHA_PRIMER_DIVIDENDO","i2","ambos","Corresponde a la fecha de pago del primer dividendo en caso de mutuo y a la primera cuota en caso de leasing. Esta fecha será la que se considera como día de pago de los meses siguientes y será la que regirá para cualquier cálculo que haga la compañía. Se deberá informar con el siguiente formato: AAAAMMDD"],["monto_dividendo_o_cuota_um","DOUBLE","unidad monetaria del instrumento","MONTO_DIVIDENDO_O_CUOTA","i2","ambos","Corresponde informar el monto del dividendo mensual para los mutuos, y el monto de la cuota mensual para los leasing, expresados en la unidad de reajustabilidad del instrumento"],["dividendo_o_cuota_final_um","DOUBLE","unidad monetaria del instrumento","DIVIDENDO_O_CUOTA_FINAL","i2","ambos","Corresponde informar el monto del último dividendo mensual para los mutuos, y el monto de la última cuota mensual para los leasing, expresados en la unidad de reajustabilidad del instrumento"],["nro_dividendos_impagos_o_cuotas_impagas","BIGINT","","NRO_DIVIDENDOS_IMPAGOS_O_CUOTAS_IMPAGAS","i2","ambos","Corresponde al número de dividendos vencidos e impagos para los mutuos y al número de cuotas impagas para los leasings. Si las cantidades son menores a tres dígitos, se debe anteponer el dígito cero (0). Si no existen dividendos o cuotas impagas, se debe informar con ceros"],["dividendos_impagos_o_cuotas_impagas_um","DOUBLE","unidad monetaria del instrumento","DIVIDENDOS_IMPAGOS_O_CUOTAS_IMPAGAS","i2","ambos","Corresponde a la sumatoria de los dividendos vencidos e impagos a la fecha de cierre del mes a que se refiere la información, expresada en la unidad de reajustabilidad del mutuo. Para el caso de los leasings, corresponde a la sumatoria del total de cuotas vencidas e impagas a la misma fecha. Si no existen dividendos o cuotas impagas, se debe informar con ceros"],["dividendos_impagos_o_cuotas_impagas_m_clp","BIGINT","miles de pesos","DIVIDENDOS_IMPAGOS_O_CUOTAS_IMPAGAS","i2","ambos","Corresponde al valor en miles de pesos (M$) del total de dividendos vencidos e impagos para los mutuos y del total de cuotas vencidas e impagas para los leasing. Si no existen dividendos o cuotas impagas, se debe informar con ceros"],["valor_comercial_um","DOUBLE","unidad monetaria del instrumento","VALOR_COMERCIAL","i2","ambos","Corresponde al valor comercial del bien hipotecado entregado en garantía, que equivale al valor de la última tasación vigente, expresado en la misma unidad de reajustabilidad del mutuo. Para los leasings, se llenará con ceros"],["valor_comercial_m_clp","BIGINT","miles de pesos","VALOR_COMERCIAL","i2","ambos","Corresponde al valor comercial en miles de pesos del bien hipotecado entregado en garantía, que equivale al valor de la última tasación vigente. Para los leasings, se llenará con ceros"],["fecha_tasacion","VARCHAR","","FECHA_TASACION","i2","ambos","Corresponde a la expresión numérica de la fecha en que se efectuó la última tasación del bien hipotecado entregado en garantía. Se deberá informar con el siguiente formato: AAAAMMDD. Para los leasings, se llenará con ceros"],["saldo_insoluto_deuda_um","DOUBLE","unidad monetaria del instrumento","SALDO_INSOLUTO_DEUDA","i2","ambos","Corresponde al valor presente de los flujos futuros de caja generados por el mutuo o contrato de leasing, descontados a la TIR de emisión, expresado en la unidad de reajustabilidad del instrumento a la fecha de cierre del mes a que se refiere la información"],["saldo_insoluto_deuda_m_clp","BIGINT","miles de pesos","SALDO_INSOLUTO_DEUDA","i2","ambos","Corresponde al valor presente en miles de pesos de los flujos futuros de caja generados por el mutuo o contrato de leasing, descontados a la TIR de emisión, a la fecha de cierre del mes a que se refiere la información"],["spread_a_la_emision","DOUBLE","","SPREAD_A_LA_EMISION","i2","ambos","Corresponde al valor del spread de tasa calculado a la emisión del contrato de leasing, según lo indicado en la NCG N° 148. Para el caso de los Mutuos Hipotecarios, se llenará con ceros"],["endoso","VARCHAR","","ENDOSO","i2","ambos","Corresponde informar si el mutuo hipotecario cuenta o no con la anotación del endoso a favor de la compañía, al margen de la inscripción hipotecaria de propiedad que garantiza el mutuo, la cual es requisito necesario para poder utilizar el mutuo hipotecario como in versión representativa de reservas técnicas y patrimonio de riesgo. De acuerdo con la siguiente codificación: SI: el mutuo cuenta con la anotación del endoso al margen. NO: el mutuo no cuenta con la anotación del endoso al margen"],["saldo_plazo_contrato","BIGINT","","SALDO_PLAZO_CONTRATO","i2","ambos","Se deberá informar los meses restantes del contrato de leasing o mutuos hipotecarios a contar de la fecha de información"],["rut_deudor_sindicado","VARCHAR","","RUT_DEUDOR","i2","ambos","Se debe informar el RUT del deudor"],["nombre_deudor","VARCHAR","","NOMBRE_DEUDOR","i2","ambos","Se debe informar el nombre del deudor del crédito"],["porcentaje_participacion_compania","DOUBLE","","PORCENTAJE_PARTICIPACION_COMPAÑIA","i2","ambos","Corresponde informar, qué porcentaje de participación le corresponde a la compañía en el capital otorgado"],["monto_total_prestamo_m_clp","BIGINT","miles de pesos","MONTO_TOTAL_PRESTAMO","i2","ambos","Corresponde al monto total del crédito otorgado por las entidades que participan en la colocación. Este monto se deberá expresar en miles de pesos (M$)"],["rut_lider","VARCHAR","","RUT_LIDER","i2","ambos","Se deberá informar el RUT de líder o agente del crédito sindicado"],["nombre_lider","VARCHAR","","NOMBRE_LIDER","i2","ambos","Se deberá informar el nombre del Líder o agente del crédito sindicado"],["porcentaje_valor_par","DOUBLE","","PORCENTAJE_VALOR_PAR","i2","ambos","Corresponde al porcentaje de valor par al cual se adquirió el instrumento"],["valor_compra_clp","BIGINT","pesos","VALOR_COMPRA","i2","ambos","Corresponde informar el valor al cual la entidad aseguradora o reaseguradora adquirió el instrumento. Este monto deberá expresarse en pesos ($)"],["tir_sin_costo","DOUBLE","","TIR_SIN_COSTO_NCG","i2","ambos","Corresponde informar la tasa de compra según lo definido en la 311, sin considerar los costos de adquisición del instrumento"],["tir_compra","DOUBLE","","TIR_COMPRA","i2","ambos","Corresponde informar la tasa de compra según lo definido en la NCG 311, esto es, la TIR de compra que incorpora los costos de adquisición. Tratándose de instrumentos adquiridos antes de 1 de enero de 2012, la TIR_COMPRA debe ser el mismo valor informado en la TIR_SIN_COSTO"],["costo_amortizado_um","DOUBLE","unidad monetaria del instrumento","COSTO_AMORTIZADO_(UM)","i2","ambos","Corresponde informar el monto determinado según NCG 311 para aquellos instrumentos financieros clasificados como costo amortizado. En el caso de los contratos de leasing, se debe incluir el valor presente del contrato a TIR de compra. Este monto deberá expresarse en unidades monetarias originales"],["costo_amortizado_clp","BIGINT","pesos","COSTO_AMORTIZADO_($)","i2","ambos","Corresponde informar el monto determinado según NCG 311 para aquellos instrumentos financieros clasificados como costo amortizado. En el caso de los contratos de leasing, se debe incluir el valor presente del contrato a TIR de compra. Este monto deberá expresarse en pesos ($)"],["tir_mercado","DOUBLE","","TIR_MERCADO","i2","ambos","Corresponde informar la tasa de mercado, utilizada para la valorización a la fecha de información, según lo indicado en la normativa de valorización"],["valor_razonable_clp","BIGINT","pesos","VALOR_RAZONABLE","i2","ambos","Corresponde al valor total de los flujos futuros del instrumento actualizados a la TIR de mercado. Este monto deberá expresarse en pesos ($)"],["deterioro_clp","BIGINT","pesos","DETERIORO","i2","ambos","Corresponde al deterioro de la inversión, según lo señalado en la Norma de Carácter General N°311, del 28.06.2011. Este monto deberá expresarse en pesos ($)"],["valor_final_m_clp","BIGINT","miles de pesos","VALOR_FINAL","i2","ambos","Corresponde al valor que tiene el instrumento a la fecha de cierre del mes a que se refiere la información, según lo establecido en Circular de Valorización de Inversiones vigente. Este monto se deberá expresar en miles de pesos (M$). Para el caso de los contratos de leasing este valor corresponde al Valor presente a tir de compra ($) del contrato menos la provisión por cuotas morosasmás el crédito a que se refiere el párrafo segundo del número 2 de la NCG N°316 o la que la reemplace"],["custodia_inv","VARCHAR","","CUSTODIA_INV","i2","ambos","Corresponde informar para cada instrumento, el tipo de custodia que presenta, de acuerdo a la siguiente codificación: CIA : Custodia en Compañía. DCV: Custodia en DCV, solo si la Cía. actuó como Depositante. EXT : Custodia en Otra entidad"],["nombre_custodio","VARCHAR","","NOMBRE_CUSTODIO","i2","ambos","Corresponde informar el nombre de la entidad que custodia la inversión en el evento que se informe en el campo CUSTODIA_INV, el código EXT (otra entidad de custodia). En caso de que no corresponda informar, se deberá llenar con espacios este campo"],["susceptibles_de_custodia","VARCHAR","","SUSCEPTIBLES_DE_CUSTODIA","i2","ambos","Se deberá informar si el instrumento es susceptible de ser custodiado de acuerdo a lo dispuesto en Circular N° 88 del Depósito Central de Valores S.A., y sus modificaciones posteriores, de acuerdo a la siguiente codificación: S: es susceptible de ser custodiado. N: no es susceptible de ser custodiado"],["garantia_estatal","VARCHAR","","GARANTIA_ESTATAL","i2","desde 2024-12","Se deberá informar si el instrumento cuenta con garantía por parte del Estado hasta la total extinción del instrumento, en consonancia con lo señalado en la letra a) del N°1 del artículo 21 del DFL N° 251, de 1931. S: El instrumento SI cuenta con garantía por parte del Estado hasta la total extinción del instrumento. N: El instrumento cuenta NO con garantía por parte del Estado hasta la total extinción del instrumento. Este campo debe informarse sólo para los instrumentos emitidos por empresas, para los demás instrumentos deberá llenarse con espacios"],["incremento_riesgo","VARCHAR","","INCREMENTO_RIESGO","i2","desde 2024-12","Corresponde informar si la situación del riesgo crediticio del instrumento financiero se ha incrementado significativamente desde el reconocimiento inicial, según lo instruido en la materia por la NCG N°311 e IFRS 9: S : Si el riesgo crediticio del instrumento financiero SI se ha incrementado significativamente. N : Si el riesgo crediticio del instrumento financiero NO se ha incrementado significativamente"],["plazo_al_vencimiento","BIGINT","","PLAZO_AL_VENCIMIENTO","i2","desde 2024-12","Se deberá informar los meses restantes al vencimiento del instrumento a contar de la fecha de información"],["duracion","DOUBLE","","DURACIÓN","i2","desde 2024-12","Corresponde al promedio ponderado en años de los vencimientos de sus flujos de caja, donde los ponderadores son el valor presente de cada flujo como una proporción del precio del instrumento"],["tipo_amortizacion","BIGINT","","TIPO_AMORTIZACIÓN","i2","desde 2024-12","Corresponde informar el tipo amortización del instrumento de renta fija, de acuerdo a la siguiente clasificación: 1: Cero 2: Francés 3: Bullet 16 4: Baloon 0: Otra"],["subyacente","VARCHAR","","SUBYACENTE","i2","desde 2024-12","Se deberá informar, para los instrumentos tipo BS, el tipo de activo al que corresponde el/los subyacente(s) , de acuerdo a la siguiente Codificación: M: Mutuos Hipotecarios. C: Créditos de Consumo. L: Contratos de Leasing. T: Tarjetas de Crédito. X: Cuentas por Cobrar. A: Créditos Automotriz. O: Otro. NA: Para Otro tipo de instrumento distinto a BS.” Por ejemplo Si el subyacente son mutuos hipotecarios y leasing, se debe informar “ML” y el resto de los caracteres en blanco"],["efecto_patrimonio","VARCHAR","","EFECTO_PATRIMONIO","i2","desde 2024-12","Corresponde informar si una inversión, es valorizada a Valor razonable (VR) con cambios en otro resultado integral: SI: Con cambios en otro resultado integral. NO: Sin cambios en otro resultado integral. NA: Inversión valorizada a Costo Amortizado"],["fin_cleas","VARCHAR","","FIN_CLEAS","i2","desde 2024-12","Para el caso de leasing, se debe indicar si el financiamiento será utilizado para la construcción, de acuerdo a la siguiente codificación: S: Si N: No Para el caso de mutuos, completar con espacios"],["deuda_garantia_otorgamiento","DOUBLE","","DEUDA_GARANTIA_OT_OR","i2","desde 2024-12","Se deberá informar la relación entre deuda y garantía del contrato de leasing o mutuo hipotecario a la fecha de otorgamiento. Por ejemplo, si para un registro el valor es 56,78%, se deberá informar 00567800"],["deuda_garantia_informacion","DOUBLE","","DEUDA_GARANTIA_PE","i2","desde 2024-12","Se deberá informar la relación entre deuda y garantía del contrato"],["clasificacion_bco_lider","VARCHAR","","CLASIFICACION_BCO_LIDER","i2","desde 2024-12","Se deberá informar si el Crédito Sindicado se encuentra o no en Cartera Normal, de acuerdo con la siguiente codificación: SI: el crédito sindicado se encuentra en Cartera Normal. NO: el crédito sindicado no se encuentra en Cartera Normal"]]},"derivados":{"cabecera":["columna","tipo","unidad","nombre en la ficha CMF","registro","vigencia","descripción"],"filas":[["periodo","VARCHAR","","","","ambos","Mes de la cartera informada (AAAA-MM)."],["sector","VARCHAR","","","","ambos","vida (archivos CSVID) o generales (CSGEN)."],["rut_aseguradora","VARCHAR","","","","ambos","RUT de la compañía de seguros, con dígito verificador (une con seguros.lista_entidades)."],["nombre_aseguradora","VARCHAR","","","","ambos","Nombre de la compañía tal como aparece en el encabezado del archivo del mes."],["tipo_registro","VARCHAR","","","","ambos","Subtipo de registro dentro del archivo (por ejemplo forward, swap o deuda)."],["objetivo_contrato","VARCHAR","","OBJETIVO_CONTRATO","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Corresponde informar el objetivo del contrato derivado, de acuerdo a lo señalado en la NCG N°200 de fecha 07.08.2006. Se señalará de acuerdo a la siguiente codificación: INV : Inversión CBE : Cobertura de riesgos financieros"],["tipo_operacion","VARCHAR","","TIPO_OPERACION","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Código que identifica las operaciones informadas por la compañía, deben informarse todas las operaciones vigentes a la fecha de presentación de la información. Se informará de acuerdo a la codificación definida en la página web de esta Superintendencia en el módulo SEIL, Codificación S.V.S., Instrumentos"],["folio_operacion","BIGINT","","FOLIO_OPERACION","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Corresponde al número de la papeleta de la mesa de dinero de la compañía, donde se registra la compra del instrumento derivado. En caso de no poder obtener este número se deberá asociar al documento contable que respalda la compra del instrumento"],["item_operacion","BIGINT","","ITEM_OPERACION","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Secuencia del instrumento derivado dentro del folio de la operación. No pueden existir dos instrumentos derivados con igual folio e ítem operación"],["fecha_de_la_operacion","VARCHAR","","FECHA_DE_LA_OPERACION","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Corresponde informar la fecha de inicio del contrato con el siguiente formato: AAAAMMDD"],["fecha_de_vencimiento_del_contrato","VARCHAR","","FECHA_DE_VENCIMIENTO_DEL_CONTRATO","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Corresponde informar la fecha de término del contrato con el siguiente formato: AAAAMMDD"],["nombre","VARCHAR","","NOMBRE","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Corresponde informar el nombre o razón social de la contraparte de la operación. Para el caso de las operaciones realizadas con bancos nacionales se informará de acuerdo a codificación definida en SEIL, Codificación SVS, Códigos Circular 1835, Códigos de Bancos, Nombre del Banco para C.1835"],["nacionalidad","VARCHAR","","NACIONALIDAD","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Corresponde informar la nacionalidad de la contraparte de la operación, de acuerdo a la codificación definida en SEIL, Codificación SVS, Países"],["relacionado","VARCHAR","","RELACIONADO","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Corresponde informar si la contraparte de la operación está relacionada con la compañía de seguros, de acuerdo a lo establecido en el artículo N°100 de la ley N°18.045 del 22.10.1981 y modificaciones. Se señalará de acuerdo a la siguiente codificación: RE : Relacionado NR : No Relacionado"],["clasificacion_de_riesgo","VARCHAR","","CLASIFICACION_DE_RIESGO","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Corresponde informar la menor clasificación de riesgo vigente de la contraparte de la operación. Si la contraparte no contara con clasificación de riesgo se debe informar S/C"],["activo_objeto_posicion_larga","VARCHAR","","ACTIVO_OBJETO_POSICION_LARGA","p2 (opcion), p3 (forward), p4 (futuro)","ambos","Corresponde informar el activo objeto para opciones con posición larga, para opciones con posición corta indicar NO APLICA"],["activo_objeto_posicion_corta","VARCHAR","","ACTIVO_OBJETO","p2 (opcion), p3 (forward), p4 (futuro)","ambos","Corresponde informar el activo objeto para opciones con posición"],["activo_objeto_unidades","DOUBLE","","ACTIVO_OBJETO","p2 (opcion)","ambos","Corresponde al número de unidades del activo subyacente de cada"],["moneda","VARCHAR","","MONEDA","p2 (opcion), p3 (forward), p4 (futuro)","ambos","Corresponde a la moneda en la cual está denominado el derivado, cuando corresponda. Se informará de acuerdo a la codificación definida en el sitio web de esta Superintendencia en el módulo SEIL, Codificación SVS, Unidad Monetaria. De no existir, se deberá consultar a esta Superintendencia"],["precio_de_ejercicio","DOUBLE","","PRECIO_DE_EJERCICIO","p2 (opcion)","ambos","Precio de intercambio a futuro fijado en el contrato, por una unidad del activo subyacente. Debe ser expresado en la moneda en la cual está denominado el derivado"],["precio_spot_del_activo_subyacente","DOUBLE","","PRECIO_SPOT_DEL_ACTIVO_SUBYACENTE","p2 (opcion), p3 (forward), p4 (futuro)","ambos","Corresponde al precio de cierre observado del activo subyacente a la opción, a la fecha de la información. En caso de Opción sobre moneda, corresponde al valor de la moneda en el mercado contado a la fecha de información. En caso de Opción sobre tasa o renta fija, corresponde a la tasa vigente en el mercado o al valor de mercado del instrumento de renta fija a la fecha de información. En caso de Opción sobre acción o índice accionario, corresponde al valor bursátil de la acción o índice accionario, en el mercado contado a la fecha de información. Debe ser expresado en la moneda en la cual está denominado el derivado"],["prima_de_la_opcion_monto","DOUBLE","","PRIMA_DE_LA_OPCION_monto","p2 (opcion)","ambos","Corresponde informar el valor pagado o recibido por la suscripción de la opción"],["prima_de_la_opcion_moneda","VARCHAR","","PRIMA_DE_LA_OPCION_moneda","p2 (opcion)","ambos","Corresponde informar la moneda en que se encuentra expresada la prima de la opción, de acuerdo a la codificación definida en SEIL, Codificación SVS, Unidades Monetarias"],["valor_razonable_del_activo_objeto_a_la_fecha_de_informacion_monto","BIGINT","","VALOR_RAZONABLE_DEL_ACTIVO_OBJETO_A_LA_FECHA_DE_INFORMACION_monto","p2 (opcion)","ambos","Corresponde informar el precio spot del activo objeto a la fecha de información multiplicado por el número de unidades del activo subyacente de cada contrato (M$)"],["numero_de_contratos","BIGINT","","NUMERO_DE_CONTRATOS","p2 (opcion), p4 (futuro)","ambos","Corresponde informar el número de contratos comprados o vendidos en cada operación"],["valor_razonable_m_clp","BIGINT","miles de pesos","VALOR_RAZONABLE","p2 (opcion)","ambos","Corresponde al valor razonable de la opción, a la fecha de cierre del mes a que se refiere la información (M$)"],["origen_de_la_informacion","VARCHAR","","ORIGEN_DE_LA_INFORMACION","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Corresponde a la fuente de donde se obtuvieron los datos para valorizar el contrato"],["activo_respalda_reserva_valor_de_fondo","VARCHAR","","ACTIVO_RESPALDA_RESERVA_VALOR_DE_FONDO","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Corresponde informar si uno o más títulos (en caso de haber agrupado instrumentos con características idénticas) registrados, se encuentran respaldando la reserva de valor del fondo señalada en el DFL Nº251. Se informará de acuerdo a la valorización que tengan los títulos, según Circular N°1360 y posteriores modificaciones, con un código de cinco letras formado de la siguiente manera: Las tres primeras letras serán: APV : si los instrumentos respaldan la reserva de valor del fondo de seguros con ahorro previsional voluntario, o OTR : si los instrumentos respaldan la reserva de valor del fondo de seguros con ahorro, distinto a los seguros con ahorro previsional voluntario. La cuarta letra será A, B, C o D dependiendo de la forma de constitución de la reserva de descalce a que se refiere el N°4 de la Norma de Carácter General N°132, de 13 de marzo de 2002 y sus posteriores modificaciones. La quinta letra será G si se garantiza la rentabilidad del valor de la"],["nombre_del_fondo","VARCHAR","","NOMBRE_DEL_FONDO","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Para instrumentos que estén asociados a fondos que respalden seguros de vida con cuenta de inversión, se debe informar el nombre del Fondo al cual pertenece. Se entenderá por fondo al tipo de plan o modalidades de inversión convenidos para los seguros con cuentas de inversión. Para instrumentos que no respalden seguros de vida con cuenta de inversión, se debe informar “NO APLICA”"],["nombre_cartera","VARCHAR","","NOMBRE_CARTERA","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Para instrumentos que no respalden seguros de vida con cuenta de inversión, se debe informar la sub cartera que respalda, si corresponde. Para instrumentos que no respalden una sub cartera, se debe informar “NO APLICA”"],["monto_activos_en_margen_m_clp","BIGINT","miles de pesos","MONTO_ACTIVOS_EN_MARGEN","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Se deberá informar el valor final, a la fecha de información, de los activos entregados como margen en la operación, expresado en miles de pesos (M$). Si para la operación no es necesario dejar activos en margen indicar cero"],["monto_activo_m_clp","BIGINT","miles de pesos","MONTO_activo","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Corresponde informar el monto contabilizado en activos producto de este contrato, es decir, el producto entre el valor de la opción a la fecha de la información y el número de contratos. Este monto se deberá expresar en miles de pesos (M$)"],["monto_pasivo_m_clp","BIGINT","miles de pesos","MONTO_pasivo","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Corresponde informar el monto contabilizado en pasivos producto de este contrato, es decir, el producto entre el valor de la opción a la fecha de la información y el número de contratos. Este monto se deberá expresar en miles de pesos (M$)"],["efecto_en_resultados_realizados_m_clp","BIGINT","miles de pesos","EFECTO_EN_RESULTADOS_REALIZADOS","p2 (opcion), p3 (forward), p5 (swap)","ambos","Corresponde informar el efecto realizado en los resultados de las operaciones a la fecha de los estados financieros. Este monto se deberá expresar en miles de pesos (M$)"],["tsa","VARCHAR","","TSA","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Corresponde informar si el instrumento está incluido en el Test de Suficiencia de Activos para el periodo informado, de acuerdo a la siguiente codificación: SI: el instrumento es utilizado para el análisis del Test de Suficiencia de Activos NO: el instrumento no es utilizado para el análisis del Test de Suficiencia de Activos. En periodos que no corresponde enviar el Test de Suficiencia de Activos"],["metod_clasif_valo","VARCHAR","","METOD_CLASIF_VALO","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","ambos","Corresponde informar la clasificación dada al instrumento en los"],["activo_objeto_posicion_larga_unidades","DOUBLE","","ACTIVO_OBJETO_POSICION_LARGA","p3 (forward), p4 (futuro)","ambos","Corresponde informar el número de unidades del activo subyacente en el cual esta expresada la posición larga de cada contrato"],["activo_objeto_posicion_corta_unidades","DOUBLE","","ACTIVO_OBJETO_POSICION_CORTA","p3 (forward), p4 (futuro)","ambos","Corresponde informar el número de unidades del activo subyacente en el cual esta expresada la posición corta de cada contrato"],["precio_forward_contrato","DOUBLE","","PRECIO_FORWARD_CONTRATO","p3 (forward)","ambos","Corresponde informar el precio a futuro establecido en el contrato. En caso de un forward de moneda corresponde informar el valor al cual será intercambiada la moneda de acuerdo a la posición que tenga la compañía en el contrato. Para un forward de tasa o renta fija corresponde informar la tasa o precio que será intercambiada de acuerdo a la posición en el contrato forward. Si se trata de un forward de acción e índice accionario corresponde informar el precio al cual será intercambiada la acción o índice al vencimiento del contrato"],["valor_de_mercado_del_activo_objeto_a_la_fecha_de_informacion_monto","DOUBLE","","VALOR_DE_MERCADO_DEL_ACTIVO_OBJETO_A_LA_FECHA_DE_INFORMACION_monto","p3 (forward), p4 (futuro)","ambos","Corresponde informar el precio spot del activo objeto a la fecha de información multiplicado por el número de unidades del activo subyacente de cada contrato (M$)"],["precio_forward_mercado","DOUBLE","","PRECIO_FORWARD_MERCADO","p3 (forward)","ambos","Precio forward de mercado a la fecha de valorización, para un contrato de similares características al valorizado, entendiéndose por características del contrato, el activo subyacente y la fecha que le resta al vencimiento desde la fecha de valorización. Este debe ser expresado de acuerdo a la moneda extranjera establecida por contrato a ser entregada o recibida en una fecha futura. Corresponderá al informado por los mercados donde se transaron los respectivos contratos, pudiendo ser obtenido desde medios de información de reconocido prestigio internacional. En caso de no existir dicho valor de mercado, corresponderá al Tipo de cambio spot o de mercado a la fecha de valorización"],["tasa_descuento_de_flujos","DOUBLE","","TASA_DESCUENTO_DE_FLUJOS","p3 (forward)","ambos","Corresponde a la tasa de interés real anual de mercado para operaciones similares a plazos equivalentes a la madurez del contrato o a la Tir de compra para los derivados que cubren activos acogidos a la Circular N° 1512"],["valor_razonable_del_contrato_a_la_fecha_de_la_informacion","BIGINT","","VALOR_RAZONABLE_DEL_CONTRATO_A_LA_FECHA_DE_LA_INFORMACION","p3 (forward)","ambos","Corresponde al valor que presenta el contrato forward a la fecha de información, que se define como el valor actual de la diferencia entre el precio forward de mercado para un contrato de similares características menos el precio forward fijado en el contrato, multiplicado por los nominales del activo objeto que se tiene derecho a comprar o vender. En el caso de derivados que cubran activos acogidos a la Circular N°1.512, corresponde al valor del contrato utilizando la TIR de Compra, multiplicado por los nominales del activo objeto que se tiene derecho a comprar o vender (M$)"],["precio_futuro_de_mercado_al_inicio_de_la_operacion","DOUBLE","","PRECIO_FUTURO_DE_MERCADO_AL_INICIO_DE_LA_OPERACIÓN","p4 (futuro)","ambos","Corresponde al precio futuro de mercado del contrato a la fecha de cierre del trimestre anterior; o bien, a la fecha de inicio de la operación si es que ésta se efectúo durante el trimestre que se está informando"],["precio_futuro_de_mercado_a_la_fecha_de_informacion","DOUBLE","","PRECIO_FUTURO_DE_MERCADO_A_LA_FECHA_DE_INFORMACION","p4 (futuro)","ambos","Corresponde al precio futuro de mercado a la fecha de información, para un contrato de idénticas características. Este debe ser expresado de acuerdo a la moneda extranjera establecida por contrato a ser entregada o recibida en una fecha futura. Corresponderá al informado por los mercados donde se transaron los respectivos contratos, pudiendo ser obtenido desde medios de información de reconocido prestigio internacional. En caso de no existir dicho valor de mercado, corresponderá al Tipo de cambio spot o de mercado a la fecha de valorización"],["valor_razonable_del_contrato_futuro_a_la_fecha_de_informacion","BIGINT","","VALOR_RAZONABLE_D_EL_CONTRATO_FUTURO_A_LA_FECHA_DE_INFORMAC","p4 (futuro)","ambos","Para aquellos Futuros que no tengan compensación diaria se debe informar el valor neto de la posición del futuro, el cual corresponde a la diferencia entre los montos contabilizados en activos y pasivos producto de este contrato, a la fecha de cierre en miles de pesos (M$)"],["activo_objeto_posicion_larga_nocional","DOUBLE","","ACTIVO_OBJETO_POSICION_LARGA","p5 (swap)","ambos","Corresponde al Valor nocional establecido por contrato, que será recibido en una fecha futura por la compañía"],["activo_objeto_posicion_corta_nocional","DOUBLE","","ACTIVO_OBJETO_POSICION_CORTA","p5 (swap)","ambos","Corresponde al Valor nocional establecido por contrato, que será entregado en una fecha futura por la compañía"],["moneda_posicion_larga","VARCHAR","","MONEDA_POSICION_LARGA","p5 (swap)","ambos","Corresponde a la moneda en la cual está expresada la posición larga en el contrato swap, es decir la moneda en que está denominada la tasa o el nocional, que debe ser recibido en una fecha futura, cuando corresponda. Se informará de acuerdo a la codificación definida en el sitio web de esta Superintendencia en el módulo SEIL, Codificación SVS, Unidades Monetarias. De no existir, se deberá consultar a esta Superintendencia"],["moneda_posicion_corta","VARCHAR","","MONEDA_POSICION_CORTA","p5 (swap)","ambos","Corresponde a la moneda en la cual está expresada la posición corta en el contrato swap, es decir la moneda en que está denominada la tasa o el nocional, que debe ser entregado en una fecha futura, cuando corresponda. Se informará de acuerdo a la codificación definida en el sitio web de esta Superintendencia en el módulo SEIL, Codificación SVS, Unidades Monetarias. De no existir, se deberá consultar a esta Superintendencia"],["tasa_a_futuro_contrato_posicion_larga","VARCHAR","","TASA_A_FUTURO_CONTRATO_POSICION_LARGA","p5 (swap)","ambos","Corresponde a la tasa a futuro establecida en el contrato swap la cual generará los flujos a ser recibidos en una fecha futura, cuando corresponda. Ej.: Fija 8,5%, Libor, etc"],["tasa_a_futuro_contrato_posicion_corta","VARCHAR","","TASA_A_FUTURO_CONTRATO_POSICION_CORTA","p5 (swap)","ambos","Corresponde a la tasa a futuro establecida en el contrato swap la cual generará los flujos a ser entregados en una fecha futura, cuando corresponda. Ej: Fija 7,4%, Libor, etc"],["t_c_futuro_contrato","DOUBLE","","T._C._FUTURO_CONTRATO","p5 (swap)","ambos","Corresponde al tipo de cambio a futuro establecido en el contrato swap y deberá ser expresado de acuerdo a la moneda extranjera establecida por contrato a ser entregada o recibida en una fecha futura"],["tasa_a_futuro_mercado_posicion_larga","DOUBLE","","TASA_A_FUTURO_MERCADO_POSICION_LARGA","p5 (swap)","ambos","Corresponde a la tasa de interés única, que aplicada a cada flujo del swap de la posición larga, genera el mismo valor presente que al valorizar cada flujo usando la estructura cero cupón de mercado a la fecha"],["tasa_a_futuro_mercado_posicion_corta","DOUBLE","","TASA_A_FUTURO_MERCADO_POSICION_CORTA","p5 (swap)","ambos","Corresponde a la tasa de interés única, que aplicada a cada flujo del swap de la posición corta, genera el mismo valor presente que al valorizar cada flujo usando la estructura cero cupón de mercado a la fecha"],["tipo_de_cambio_me","DOUBLE","","TIPO_DE_CAMBIO_ME","p5 (swap)","ambos","Tipo de cambio spot de mercado a la fecha de valorización"],["valor_presente_posicion_larga_m_clp","BIGINT","miles de pesos","VALOR_PRESENTE_POSICION_LARGA","p5 (swap)","ambos","Corresponde al valor actual de los flujos a recibir descontados a la tasa de mercado posición larga o a Tir de compra según corresponda"],["valor_presente_posicion_corta_m_clp","BIGINT","miles de pesos","VALOR_PRESENTE_POSICION_CORTA","p5 (swap)","ambos","Corresponde al valor actual de los flujos a entregar descontados a la tasa de mercado posición corta o a Tir de compra según corresponda"],["valor_razonable_del_activo_objeto_a_la_fecha_de_la_informacion_m_clp","BIGINT","miles de pesos","VALOR_RAZONABLE_DEL_ACTIVO_OBJETO_A_LA_FECHA_DE_LA_INFORMACION","p5 (swap)","ambos","Corresponde informar, en caso de: Swaps de monedas: el valor de mercado de la moneda multiplicada por los nominales del contrato Swaps de tasa de interés: el valor presente del nocional o de referencia del contrato Swaps sobre instrumento de renta fija: el número de unidades del instrumento o índice por el precio spot a la fecha de la información"],["valor_razonable_del_contrato_a_la_fecha_de_la_informacion_m","BIGINT","","VALOR_RAZONABLE_D_EL_CONTRATO_A_LA_FECHA_DE_LA_INFORMACION_(M$)","p5 (swap)","ambos","Corresponde al valor razonable que presenta el contrato swap, o uno de similares características, a la fecha de información. En el caso de derivados que cubran activos acogidos a la Circular N°1.512, corresponde al valor del contrato utilizando la TIR de compra"],["tipo_contrato","BIGINT","","TIPO_CONTRATO","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","desde 2024-12","Se debe informar el tipo de subyacente sobre el cual está realizado el contrato, de acuerdo con la siguiente codificación: 01: Tasas de interés o inflación 02: Monedas extranjeras 110 03: Acciones o Índices Accionarios"],["rut_contraparte_nacional","VARCHAR","","RUT_CONTRAPARTE_NACIONAL","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","desde 2024-12","informa sólo para contrapartes nacionales. En caso de contrapartes extranjeras, se deberá informar con ceros (0). Dígito verificador del RUT de la contraparte. Este campo se informa"],["lei_contraparte_extranjera","VARCHAR","","LEI_CONTRAPARTE_EXTRANJERA","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","desde 2024-12","En caso de contrapartes nacionales, o contrapartes extranjeras que no tuvieran código LEI, se deberá informar con espacios"],["tipo_contraparte","BIGINT","","TIPO_CONTRAPARTE","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","desde 2024-12","Se debe informar el tipo de contraparte de acuerdo con la siguiente codificación: 01: ECC (entidades de contraparte central) nacional 02: Banco nacional 03: Otras autorizadas CMF nacional 04: ECC (entidades de contraparte central) en el exterior 05: Banco exterior 06: Otras en el exterior"],["cm_compensacion_bilateral","VARCHAR","","CM_COMPENSACION_BILATERAL","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","desde 2024-12","Corresponde indicar si el contrato de derivado se ampara bajo un Central de Chile, de acuerdo con la siguiente codificación: SI: El contrato ha sido celebrado bajo el amparo de un contrato marco de compensación bilateral de aquellos reconocidos por el Banco Central de Chile. NO: El contrato no ha sido celebrado bajo el amparo de un contrato marco de compensación bilateral de aquellos reconocidos por el Banco Central de Chile"],["tipo_documentacion","BIGINT","","TIPO_DOCUMENTACIO","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","desde 2024-12","Se debe indicar el tipo de contrato marco bajo el cual se ampara la"],["anexo_garantia","VARCHAR","","ANEXO_GARANTÍA","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","desde 2024-12","Para el caso de que el contrato de derivados haya sido celebrado bajo el amparo de un contrato marco, corresponde informar si dicho contrato marco cuenta con anexo de garantías, según la siguiente codificación: SI: El contrato marco cuenta con anexo de garantías NO: El contrato marco no cuenta con anexo de garantías 112 NA: En caso que la operación que se informa, no haya sido celebrada bajo el amparo de un contrato marco"],["identificador_garantia","VARCHAR","","IDENTIFICADOR_GARANTIA","p2 (opcion), p3 (forward), p4 (futuro), p5 (swap)","desde 2024-12","Sólo se debe informar el identificador para instrumentos derivados que posean márgenes de variación. En caso de que no corresponda informar un código, se deberá completar con espacios"],["nocional_posicion_larga_monto","BIGINT","","NOCIONAL_POSICION_LARGA_monto","p3 (forward), p4 (futuro), p5 (swap)","desde 2024-12",""],["nocional_posicion_corta_monto_m_clp","BIGINT","miles de pesos","NOCIONAL_POSICION_CORTA_monto","p3 (forward), p4 (futuro), p5 (swap)","desde 2024-12","contrato, expresado en M$, a la fecha de la información"],["valor_razonable_del_contrato_a_la_fecha_de_la_informacion_ec","BIGINT","","VALOR_RAZONABLE_DEL_CONTRATO_A_LA_FECHA_DE_LA_INFORMACION_EC","p3 (forward), p5 (swap)","desde 2024-12","Corresponde al valor que presenta el contrato forward a la fecha de el precio forward de mercado para un contrato de similares características menos el precio forward fijado en el contrato, a comprar o vender. (M$)"],["tasa_a_futuro_contrato_posicion_larga_ec","BIGINT","","TASA_A_FUTURO_CONTRATO_POSICION_LARGA_EC","p5 (swap)","desde 2024-12","Corresponde informar si la tasa de interés del contrato es fija o 02: Flotante"],["tasa_a_futuro_contrato_posicion_corta_ec","BIGINT","","TASA_A_FUTURO_CONTRATO_POSICION_CORTA_EC","p5 (swap)","desde 2024-12","Corresponde informar si la tasa de interés del contrato es fija o 02: Flotante"]]},"pactos":{"cabecera":["columna","tipo","unidad","nombre en la ficha CMF","registro","vigencia","descripción"],"filas":[["periodo","VARCHAR","","","","ambos","Mes de la cartera informada (AAAA-MM)."],["sector","VARCHAR","","","","ambos","vida (archivos CSVID) o generales (CSGEN)."],["rut_aseguradora","VARCHAR","","","","ambos","RUT de la compañía de seguros, con dígito verificador (une con seguros.lista_entidades)."],["nombre_aseguradora","VARCHAR","","","","ambos","Nombre de la compañía tal como aparece en el encabezado del archivo del mes."],["tipo_operacion","VARCHAR","","TIPO_OPERACION","p6","ambos","Código que identifica las operaciones informadas por la compañía, deben informarse todas las operaciones vigentes a la fecha de presentación de la información. Se informará de acuerdo a la codificación definida en la página web de esta Superintendencia en el módulo SEIL, Codificación S.V.S., Instrumentos"],["folio_operacion","BIGINT","","FOLIO_OPERACION","p6","ambos","En el caso que la operación corresponda a una retroventa, se debe indicar el número de la papeleta de la mesa de dinero de la compañía, donde se registra la operación subyacente al pacto. Para otro tipo de pacto se debe informar el folio de la operación de pacto. En caso de no poder obtener este número se deberá asociar al documento contable que respalda la compra del instrumento"],["item_operacion","BIGINT","","ITEM_OPERACION","p6","ambos","Secuencia dentro del folio de la operación. No pueden existir dos operaciones con igual folio e ítem operación"],["fecha_de_la_operacion","VARCHAR","","FECHA_DE_LA_OPERACION","p6","ambos","Corresponde informar la fecha de inicio del contrato de pacto con el siguiente formato: AAAAMMDD"],["fecha_de_vencimiento_del_contrato","VARCHAR","","FECHA_DE_VENCIMIENTO_DEL_CONTRATO","p6","ambos","Corresponde informar la fecha de vencimiento del contrato de pacto con el siguiente formato: AAAAMMDD"],["tasa_pacto","DOUBLE","","TASA_PACTO","p6","ambos","Corresponde informar la tasa a la cual fue realizado el pacto, indicada en el contrato de pacto"],["nombre","VARCHAR","","NOMBRE","p6","ambos","Corresponde informar el nombre o razón social de la contraparte del pacto. Para el caso de las operaciones realizadas con bancos nacionales se informará de acuerdo a codificación definida en SEIL, Codificación SVS, Códigos Circular 1835, Códigos de Bancos, Nombre del Banco para C.1835"],["nacionalidad","VARCHAR","","NACIONALIDAD","p6","ambos","Corresponde informar la nacionalidad de la contraparte del pacto, de acuerdo a la codificación definida en SEIL, Codificación SVS, Países"],["relacionado","VARCHAR","","RELACIONADO","p6","ambos","Corresponde informar si la contraparte del pacto de la operación está relacionada con la compañía de seguros, de acuerdo a lo establecido en el artículo N°100 de la ley N°18.045 del 22.10.1981 y modificaciones. Se señalará de acuerdo a la siguiente codificación: RE : Relacionado NR : No Relacionado"],["activo_objeto","VARCHAR","","ACTIVO_OBJETO","p6","ambos","Instrumento subyacente al pacto. En el caso de tratarse de un"],["serie_activo_objeto","VARCHAR","","SERIE_ACTIVO_OBJETO","p6","ambos","Corresponde informar la serie del instrumento subyacente al pacto cuando corresponda"],["nro_rut_activo_objeto","VARCHAR","","NRO_RUT_ACTIVO_OBJETO","p6","ambos","Corresponde informar el Rut del emisor del instrumento subyacente"],["valor_nominal","DOUBLE","","VALOR_NOMINAL","p6","ambos","Corresponde informar el valor nominal del instrumento subyacente a la fecha de presentación de la información. Se entiende por “nominal” los nominales comprados originalmente menos las ventas realizadas sobre este título. No se deberán rebajar las amortizaciones del instrumento a la fecha de información"],["tir_compra","DOUBLE","","TIR_COMPRA","p6","ambos","Corresponde a la tasa anual de descuento utilizada para determinar el precio del instrumento subyacente al momento de la compra"],["tasa_emision","DOUBLE","","TASA_EMISION","p6","ambos","Corresponde a la tasa a la cual fue emitido el instrumento subyacente"],["activo_objeto_valor_contable","BIGINT","","ACTIVO_OBJETO","p6","ambos","Corresponde al valor contable del instrumento subyacente al pacto"],["moneda","VARCHAR","","MONEDA","p6","ambos","Corresponde a la moneda en la cual está denominado el instrumento subyacente el pacto, cuando corresponda. Se informará de acuerdo a la codificación definida en el sitio web de esta Superintendencia en el módulo SEIL, Codificación SVS, Unidades Monetarias. De no existir, se deberá consultar a esta Superintendencia"],["tasa_o_precio_de_mercado","DOUBLE","","TASA_O_PRECIO_DE_MERCADO","p6","ambos","Tasa de mercado del instrumento subyacente al pacto, a la fecha de valorización"],["valor_de_mercado_a_la_fecha_de_suscripcion_monto","DOUBLE","","VALOR_DE_MERCADO_A_LA_FECHA_DE_SUSCRIPCION_monto","p6","ambos","Corresponde informar el monto del valor de mercado, del activo objeto a la fecha de suscripción del pacto"],["valor_inicial_um","DOUBLE","","VALOR_INICIAL_UM","p6","ambos","Corresponde al valor invertido en la operación, indicado en el contrato de pacto, expresado en la moneda del pacto"],["valor_pactado","DOUBLE","","VALOR_PACTADO","p6","ambos","Corresponde al valor del pacto al vencimiento, acordado en el contrato de pacto, expresado en la moneda del pacto"],["interes_devengado_del_pacto_m","BIGINT","","INTERES_DEVENGADO_DEL_PACTO_M$","p6","ambos","Corresponde informar el interés que resulte de aplicar la tasa implícita entre el valor de compra del activo objeto y el monto a recibir por el cumplimiento del compromiso de venta, en proporción"],["valorizacion_de_pacto_a_la_fecha_de_cierre_m_clp","BIGINT","miles de pesos","VALORIZACION_DE_PACTO_A_LA_FEC_HA_DE_CIERRE","p6","ambos","Corresponde informar el valor en que se encuentra contabilizado el pacto, de acuerdo a las instrucciones de circular sobre valorización de esta Superintendencia, a la fecha de cierre del mes a que se refiere la información, expresado en miles de pesos (M$)"],["valor_de_mercado_a_la_fecha_de_informacion","BIGINT","","VALOR_DE_MERCADO_A_LA_FECHA_DE_INFORMACION","p6","ambos","Corresponde informar el monto del valor de mercado, del activo subyacente del pacto, a la fecha de información"],["tsa","VARCHAR","","TSA","p6","ambos","Corresponde informar si el instrumento está incluido en el Test de Suficiencia de Activos para el periodo informado, de acuerdo a la siguiente codificación: SI: el instrumento es utilizado para el análisis del Test de Suficiencia de Activos NO: el instrumento no es utilizado para el análisis del Test de Suficiencia de Activos. En periodos que no corresponde enviar el Test de Suficiencia de Activos"],["metod_clasif_valo","VARCHAR","","METOD_CLASIF_VALO","p6","ambos","Corresponde informar la clasificación dada al instrumento en los"]]},"extranjeros":{"cabecera":["columna","tipo","unidad","nombre en la ficha CMF","registro","vigencia","descripción"],"filas":[["periodo","VARCHAR","","","","ambos","Mes de la cartera informada (AAAA-MM)."],["sector","VARCHAR","","","","ambos","vida (archivos CSVID) o generales (CSGEN)."],["rut_aseguradora","VARCHAR","","","","ambos","RUT de la compañía de seguros, con dígito verificador (une con seguros.lista_entidades)."],["nombre_aseguradora","VARCHAR","","","","ambos","Nombre de la compañía tal como aparece en el encabezado del archivo del mes."],["tipo_registro","VARCHAR","","","","ambos","Subtipo de registro dentro del archivo (por ejemplo forward, swap o deuda)."],["folio_operacion","BIGINT","","FOLIO_OPERACION","x2 (deuda)","ambos","Corresponde al número de la papeleta de la mesa de dinero de la compañía, donde se registra la compra del instrumento. En caso de no poder obtener este número se deberá asociar al documento contable que respalda la compra del instrumento"],["item_operacion","BIGINT","","ITEM_OPERACION","x2 (deuda)","ambos","Secuencia del instrumento dentro del folio de la operación. No pueden existir dos instrumentos con igual folio e ítem operación"],["tipo_instrumento","VARCHAR","","TIPO_INSTRUMENTO","x2 (deuda), x3 (acciones_y_fondos), x4 (bienes_raices), x5 (filiales)","ambos","Este campo es obligatorio y se informará de acuerdo a la codificación definida en SEIL, Codificación S.V.S., Instrumentos"],["valor_nominal","DOUBLE","","VALOR_NOMINAL","x2 (deuda)","ambos","Corresponde informar el valor nominal vigente del instrumento a la fecha de cierre del mes a que se refiere la información. Es decir, los nominales comprados originalmente menos las ventas realizadas sobre el mismo título. No se deberán rebajar las amortizaciones del instrumento a la fecha de valorización. Cabe señalar que cuando se hayan agrupado títulos con idénticas características en un folio de operación, corresponderá informar en este campo la suma de sus respectivos valores nominales, debiéndose anotar el monto exacto hasta con 4 decimales"],["pais","VARCHAR","","PAIS","x2 (deuda), x3 (acciones_y_fondos), x4 (bienes_raices), x5 (filiales)","ambos","Corresponde señalar el país donde se emitió el instrumento. Se informará de acuerdo a la codificación definida en SEIL, Codificación S.V.S., Países"],["estado_garante","VARCHAR","","ESTADO_GARANTE","x2 (deuda)","ambos","Corresponde señalar el estado u organismo garante del título. Este campo se llenará para el caso de instrumentos, como los Bonos Brady. Se informará de acuerdo a la codificación definida en SEIL, Codificación S.V.S., Países"],["nombre_del_emisor","VARCHAR","","NOMBRE_DEL_EMISOR","x2 (deuda)","ambos","Corresponde informar la razón social o el nombre del emisor de cada título que forma parte de las inversiones de la compañía"],["codigo_individualizacion_o_nemotecnico","VARCHAR","","CODIGO_INDIVIDUALIZACION_O_NEMOTECNICO","x2 (deuda), x3 (acciones_y_fondos)","ambos","Corresponde obligatoriamente informar el código universal “ISIN” (International Securities Identification Number), a falta de éste, el código “CUSIP” (Commitee On Uniform Securities Identification Procedures). De no existir los anteriores, se deberá consultar a esta Superintendencia"],["moneda","VARCHAR","","MONEDA","x2 (deuda), x3 (acciones_y_fondos), x4 (bienes_raices)","ambos","Corresponde señalar la moneda en la cual está expresado el valor nominal. Se informara de acuerdo a la codificación definida en SEIL, Codificación S.V.S., Unidades Monetarias"],["fecha_emision","VARCHAR","","FECHA_EMISION","x2 (deuda)","ambos","Corresponde a la expresión numérica de la fecha desde la cual se inicia el devengamiento de intereses. Se deberá informar con el siguiente formato: AAAAMMDD"],["fecha_compra","VARCHAR","","FECHA_COMPRA","x2 (deuda), x4 (bienes_raices), x5 (filiales)","ambos","Corresponde a la fecha en la cual la entidad aseguradora o reaseguradora adquirió el instrumento. Se deberá informar con el siguiente formato: AAAAMMDD"],["fecha_vencimiento","VARCHAR","","FECHA_VENCIMIENTO","x2 (deuda)","ambos","Corresponde a la fecha de vencimiento del instrumento. Se deberá informar con el siguiente formato: AAAAMMDD"],["tipo_nominales","VARCHAR","","TIPO_NOMINALES","x2 (deuda)","ambos","Corresponde a si las unidades nominales están expresadas a fecha de emisión o a fecha de vencimiento. Esto especifica la forma de obtener un valor par o presente (descontando o capitalizando). Se informará de acuerdo a la siguiente codificación: I : a fecha de emisión F : a fecha de vencimiento"],["tratamiento","VARCHAR","","TRATAMIENTO","x2 (deuda)","ambos","Corresponde a la forma de descuento del valor de los flujos futuros (interés más amortización). Se deberá codificar de la siguiente manera: CC : Con cupones. Indica que se trata de un instrumento con flujos de vencimiento regulares. SC : Sin cupones. CV : Cupones variables. Indica que se trata de un instrumento con flujos de vencimientos variables y están especificados por una fecha predefinida pudiendo no ser la misma para cada flujo"],["tasa_emision","DOUBLE","","TASA_EMISION","x2 (deuda)","ambos","Corresponde a la tasa con la cual fue emitido el instrumento de deuda de tasa fija y con la cual se construyen los flujos de la tabla de desarrollo. Para el caso de instrumentos de intermediación financiera como por ejemplo: depósitos, pagarés, u otros, se deberá informar la tasa que paga el instrumento"],["tasa_de_interes","VARCHAR","","TASA_DE_INTERES","x2 (deuda)","ambos","Corresponde señalar para los instrumentos de deuda de interés variable la tasa de interés de referencia del instrumento. Por ejemplo Libor 360 Para los instrumentos de interés fijo se llenará con la tasa fijada"],["tasa_base","VARCHAR","","TASA_BASE","x2 (deuda)","ambos","Corresponde informar la forma de cálculo de intereses del título. Se informará de acuerdo a la codificación definida en SEIL, codificación SVS, Circular 1835, Forma de cálculo de intereses"],["valor_compra_clp","BIGINT","pesos","VALOR_COMPRA","x2 (deuda)","ambos","Corresponde informar el valor al cual la entidad aseguradora o reaseguradora adquirió el instrumento. Este monto deberá expresarse en pesos ($) a la paridad del tipo de cambio de cierre de la moneda de emisión"],["tir_de_compra","DOUBLE","","TIR_DE_COMPRA","x2 (deuda)","ambos","Corresponde a la tasa de descuento utilizada para determinar el precio del instrumento al momento de la compra. Esta información será llenada para los instrumentos de deuda con tasa de interés fija, para los de interés variable se llenará con ceros (0)"],["valor_presente_tir_de_compra_m_clp","BIGINT","miles de pesos","VALOR_PRESENTE_TIR_DE_COMPRA","x2 (deuda)","ambos","Corresponde al valor presente de los flujos futuros del instrumento actualizados a la TIR de compra. Este monto deberá expresarse en miles de pesos (M$) a la paridad del tipo de cambio de cierre de la moneda de emisión. Esta información será llenada para los instrumentos de deuda con tasa de interés fija, para los de interés variable se llenará con ceros (0)"],["tir_mercado","DOUBLE","","TIR_MERCADO","x2 (deuda)","ambos","Corresponde a la tasa de mercado, a la fecha de información, para un contrato de similares características. Según lo indicado en circular de valorización"],["valor_razonable_m_clp","BIGINT","miles de pesos","VALOR_RAZONABLE","x2 (deuda), x3 (acciones_y_fondos)","ambos","Corresponde al valor total de los flujos futuros del instrumento actualizados a la TIR de mercado. Este monto deberá expresarse en miles de pesos (M$) a la paridad del tipo de cambio de cierre de la moneda de emisión"],["deterioro_m_clp","BIGINT","miles de pesos","DETERIORO","x2 (deuda), x4 (bienes_raices)","ambos","Corresponde al deterioro de la inversión, según lo señalado en la Norma de Carácter General N°311, del 28.06.2011. Este monto deberá expresarse en miles de pesos (M$)"],["valor_final_m_clp","BIGINT","miles de pesos","VALOR_FINAL","x2 (deuda), x3 (acciones_y_fondos), x4 (bienes_raices), x5 (filiales)","ambos","Corresponde al valor que tiene el instrumento a la fecha de cierre del mes a que se refiere la información, según lo establecido en Circular de Valorización de Inversiones vigente. Este monto se deberá expresar en miles de pesos (M$) a la paridad del tipo de cambio de cierre de la moneda de emisión"],["prohibicion","VARCHAR","","PROHIBICION","x2 (deuda), x3 (acciones_y_fondos)","ambos","Se deberá informar si uno o más títulos (en caso de haber agrupados instrumentos con características idénticas) registrados se encuentran afectos a prohibiciones, gravámenes u otros impedimentos señalados en el DFL Nº251. Se informará de acuerdo a la siguiente codificación: S : Si tiene prohibición. N : No tiene prohibición"],["clasificacion_de_riesgo","VARCHAR","","CLASIFICACION_DE_RIESGO","x2 (deuda), x3 (acciones_y_fondos)","ambos","Se deberá informar la menor clasificación de riesgo vigente del instrumento a la fecha de cierre del mes a que se refiere la información. Si el instrumento no contara con clasificación de riesgo se debe informar S/C"],["activo_en_margen_o_sujeto_a_pacto","VARCHAR","","ACTIVO_EN_MARGEN_O_SUJETO_A_PACTO","x2 (deuda), x3 (acciones_y_fondos)","ambos","Corresponde informar si uno o más títulos registrados (en caso de haber agrupado instrumentos con características idénticas) se encuentran otorgados como margen de las operaciones de derivados señaladas en el DFL Nº251 o si se encuentran sujetos a pacto, de acuerdo a lo señalado en la Circular de Valorización de Inversiones. Se informará el tipo de contrato al cual está asociado utilizando la codificación definida en SEIL, Codificación S.V.S., Instrumentos Derivados y Pactos. Si no está en margen se informara N"],["activo_comprado_a_traves_de_cdv","VARCHAR","","ACTIVO_COMPRADO_A_TRAVES_DE_CDV","x2 (deuda), x3 (acciones_y_fondos)","ambos","Se deberá informar si uno o más títulos (en caso de haber agrupado instrumentos con características idénticas) se adquirieron a través de CDV (Certificados de Depósito de Valores). Se informará de acuerdo a la siguiente codificación: CDV : inversión adquirida a través de CDV. Si no corresponde informar, se llenará con espacios"],["activo_respalda_reserva_valor_de_fondo","VARCHAR","","ACTIVO_RESPALDA_RESERVA_VALOR_DE_FONDO","x2 (deuda), x3 (acciones_y_fondos), x4 (bienes_raices)","ambos","Corresponde informar si uno o más títulos (en caso de haber agrupado instrumentos con características idénticas) registrados, se encuentran respaldando la reserva de valor del fondo señalada en el DFL Nº251. Se informará de acuerdo a la valorización que tengan los títulos, según Circular N°1360 y posteriores modificaciones, con un código de cinco letras formado de la siguiente manera: Las tres primeras letras serán: APV : si los instrumentos respaldan la reserva de valor del fondo de seguros con ahorro previsional voluntario, o OTR : si los instrumentos respaldan la reserva de valor del fondo de seguros con ahorro, distinto a los seguros con ahorro previsional voluntario. La cuarta letra será A, B, C o D dependiendo de la forma de constitución de la reserva de descalce a que se refiere el N°4 de la Norma de Carácter General N°132, de 13 de marzo de 2002 y sus posteriores modificaciones. La quinta letra será G sí se garantiza la rentabilidad del valor de la"],["nombre_del_fondo","VARCHAR","","NOMBRE_DEL_FONDO","x2 (deuda), x3 (acciones_y_fondos), x4 (bienes_raices)","ambos","Para instrumentos que estén asociados a fondos que respalden seguros de vida con cuenta de inversión, se debe informar el nombre del Fondo al cual pertenece. Se entenderá por fondo al tipo de plan o modalidades de inversión convenidos para los seguros con cuentas de inversión. Para instrumentos que no respalden seguros de vida con cuenta de inversión, se debe informar “NO APLICA”"],["nombre_cartera","VARCHAR","","NOMBRE_CARTERA","x2 (deuda), x3 (acciones_y_fondos), x4 (bienes_raices)","ambos","Para instrumentos que no respalden seguros de vida con cuenta de inversión, se debe informar la sub cartera que respalda, si corresponde. Para instrumentos que no respalden una sub cartera, se debe informar “NO APLICA”"],["relacionado","VARCHAR","","RELACIONADO","x2 (deuda), x3 (acciones_y_fondos)","ambos","Corresponde informar si el emisor del instrumento está relacionado con la compañía de seguros, de acuerdo a lo establecido en el artículo N°100 de la ley N°18.045 del 22.10.1981 y sus modificaciones. Se señalará de acuerdo a la siguiente codificación: RE : Relacionado NR : No Relacionado"],["clasificacion_inversion","VARCHAR","","CLASIFICACION_INVERSION","x2 (deuda), x3 (acciones_y_fondos)","ambos","Corresponde informar la clasificación de la inversión, de acuerdo a la siguiente codificación: D: Disponible para la venta. M: Mantenida hasta el vencimiento"],["tsa","VARCHAR","","TSA","x2 (deuda), x3 (acciones_y_fondos), x4 (bienes_raices), x5 (filiales)","ambos","Corresponde informar si el instrumento está incluido en el Test de Suficiencia de Activos para el periodo informado, de acuerdo a la siguiente codificación: SI: el instrumento es utilizado para el análisis del Test de Suficiencia de Activos NO: el instrumento no es utilizado para el análisis del Test de Suficiencia de Activos. En periodos que no corresponde enviar el Test de Suficiencia de Activos"],["cobertura","VARCHAR","","COBERTURA","x2 (deuda), x3 (acciones_y_fondos)","ambos","Corresponde indicar si el instrumento está cubierto por un Derivado y qué tipo de operación de acuerdo a la siguiente Codificación En el primer carácter de este campo se debe indicar: S, si el instrumento está cubierto por un Derivado N, si el instrumento no está cubierto En los caracteres 2 al 5 deberá indicar el código de operación de Derivado de acuerdo a la Codificación de Instrumentos vigente en el sitio web de la SVS Por ejemplo, si el instrumento está cubierto por un swap se debe ingresar: SS si el instrumento está cubierto por un forward de venta se debe ingresar: SFWV Si el instrumento está cubierto por más de una operación de derivado se debe informar SMIX"],["metod_clasif_valo","VARCHAR","","METOD_CLASIF_VALO","x2 (deuda), x3 (acciones_y_fondos)","ambos","Corresponde informar la clasificación dada al instrumento en los"],["criterio_valorizacion","VARCHAR","","CRITERIO_VALORIZ","x2 (deuda), x3 (acciones_y_fondos)","ambos","Corresponde indicar si la inversión está valorizada a Valor"],["modelo_valoracio","VARCHAR","","MODELO_VALORACIO","x2 (deuda), x3 (acciones_y_fondos)","ambos","Corresponde indicar si la inversión está valorizada por la"],["modelo_propio_deterioro","VARCHAR","","MODELO_PROPIO_DE_TERIORO","x2 (deuda), x3 (acciones_y_fondos)","ambos","Corresponde indicar si el Deterioro de la inversión se determinó usando una metodología propia o es una aplicación de la metodología definida en la NCG N° 311. Se informará de acuerdo a la siguiente codificación: SI : Método propio para estimar el deterioro. NO : Aplicación de la NCG N°311"],["custodiado","VARCHAR","","CUSTODIADO","x2 (deuda), x3 (acciones_y_fondos)","ambos","Se deberá informar si el instrumento se encuentra o no custodiado, de acuerdo a la siguiente codificación: S: Está custodiado N: No está custodiado"],["nombre_custodio","VARCHAR","","NOMBRE_CUSTODI","x2 (deuda), x3 (acciones_y_fondos)","ambos","Corresponde informar el nombre de la entidad que custodia la"],["clasificacion_de_riesgo_pais","VARCHAR","","CLASIFICACIÓN_DE_RIESGO_PAIS","x2 (deuda), x3 (acciones_y_fondos), x4 (bienes_raices), x5 (filiales)","ambos","Las inversiones extranjeras del N°7 de la NCG 152, deberán indicar la clasificación de riesgo del país donde se encuentra el activo o donde se encuentra registrado el instrumento financiero correspondiente. Si no corresponde informar se llenará con espacios"],["regulador","VARCHAR","","REGULADOR","x2 (deuda), x3 (acciones_y_fondos), x4 (bienes_raices), x5 (filiales)","ambos","Las inversiones extranjeras del N°7 de la NCG 152, deberán indicar organismo supervisor del mercado financiero del emisor o administrador de la inversión del N°7 de la NCG 152. Si no corresponde informar, se llenará con espacios"],["bolsa","VARCHAR","","BOLSA","x3 (acciones_y_fondos)","ambos","Corresponde informar la Bolsa de Valores en la cual se adquirió el instrumento. Para aquellos que no se transen en Bolsa, se deberá colocar NT (no transa)"],["rut_administradora","VARCHAR","","RUT_ADMINISTRADORA","x3 (acciones_y_fondos)","ambos","Se deberá informar el RUT de la administradora del fondo en caso que corresponda. Si no corresponde informar, se llenará con ceros"],["run","VARCHAR","","RUN","x3 (acciones_y_fondos)","ambos","Se deberá informar el RUN de cada fondo que forma parte de las inversiones de la compañía, de acuerdo a codificación definida en SEIL, Codificación S.V.S., Fondos de Inversión o Fondos Mutuos. Si no corresponde informar, se llenará con ceros"],["nombre_emisor","VARCHAR","","NOMBRE_EMISOR","x3 (acciones_y_fondos)","ambos","Corresponde informar la razón social o el nombre del emisor de cada título que forme parte de las inversiones de la compañía. De acuerdo a lo indicado en Anexo N° 6"],["serie","VARCHAR","","SERIE","x3 (acciones_y_fondos)","ambos","Se deberá informar la serie del instrumento cuando corresponda"],["tipo_fondo","VARCHAR","","TIPO_FONDO","x3 (acciones_y_fondos)","ambos","Para los fondos mutuos y fondos de inversiones se debe informar el tipo de fondo según la siguiente clasificación: IN : Inmobiliario. CR : Capital de Riesgo. IE : Infraestructura OT : Otros. Para las acciones se deberá informar: AC"],["unidades","DOUBLE","","UNIDADES","x3 (acciones_y_fondos)","ambos","Corresponde al número de acciones o cuotas de propiedad de la entidad a la fecha de cierre del mes a que se refiere la información"],["requisito_presencia","VARCHAR","","REQUISITO_PRESENCIA","x3 (acciones_y_fondos)","ambos","Corresponde indicar si el instrumento cumple con los requisitos de presencia indicados en la normativa vigente. Se informará de acuerdo a la codificación definida en SEIL, codificación SVS, Circular 1835, Requisito presencia"],["valor_bursatil_unitario","DOUBLE","","VALOR_BURSATIL_UNITARIO","x3 (acciones_y_fondos)","ambos","Corresponde al valor bolsa de la cuota o de la acción definido en Circular de Valorización, observado en la Bolsa de Valores donde se adquirió el título; y deberá expresarse en moneda de emisión del instrumento. Si no corresponde, esta información será llenada con ceros (0)"],["valor_libro_m_clp","BIGINT","miles de pesos","VALOR_LIBRO","x3 (acciones_y_fondos)","ambos","Para el caso de las cuotas de fondos de inversión nacionales cuyos activos estén invertidos en el extranjero, se indicará el valor libro de la cuota. El valor libro corresponde al patrimonio del fondo dividido por el número total de cuotas pagadas a la fecha de cierre del mes a que se refiere la información por el número de unidades, este monto se deberá expresar en (M$). Este campo se informará con ceros, si el instrumento informado es distinto al indicado"],["valor_bursatil_m_clp","BIGINT","miles de pesos","VALOR_BURSATIL","x3 (acciones_y_fondos)","ambos","Corresponde al valor bursátil unitario, multiplicado por el número de unidades de propiedad de la compañía; deberá expresarse en miles de pesos (M$). Si no corresponde, esta información será llenada con ceros (0)"],["costo_historico_m_clp","BIGINT","miles de pesos","COSTO_HISTORICO","x3 (acciones_y_fondos)","ambos","Corresponde al valor de compra promedio ponderado de las acciones, expresado en miles de pesos (M$). Esta información para las cuotas de fondos será llenada con ceros (0)"],["valor_cuota","DOUBLE","","VALOR_CUOTA","x3 (acciones_y_fondos)","ambos","Corresponde al valor de cierre de la cuota del fondo del último día hábil bursátil del mes a que se refiere la información, expresados en moneda de emisión de la cuota. Esta información para las acciones será llenada con ceros (0)"],["unidades_en_margen","DOUBLE","","UNIDADES_EN_MARGEN","x3 (acciones_y_fondos)","ambos","Corresponde informar el número de acciones o de cuotas de fondos que se encuentran otorgados como margen de las operaciones de derivados señaladas en el DFL Nº251, o sujeto a pacto"],["filial_coligada","VARCHAR","","FILIAL_COLIGADA","x3 (acciones_y_fondos)","ambos","Se debe informar si la inversión informada corresponde a una empresa Filial o Coligada de acuerdo a la circular 2022, utilizando la siguiente codificación: FI: Empresa Filial CO: Empresa Coligada NA: Empresa que no es Filial o Coligada"],["descripcion_del_local","VARCHAR","","DESCRIPCION_DEL_Local","x4 (bienes_raices)","ambos","Se indicará si es un local. S : Si N : No"],["descripcion_del_oficina","VARCHAR","","DESCRIPCION_DEL_Oficina","x4 (bienes_raices)","ambos","Se indicará si es una oficina. S : Si N : No"],["descripcion_del_bodega","VARCHAR","","DESCRIPCION_DEL_Bodega","x4 (bienes_raices)","ambos","Se indicará si es una bodega. S : Si N : No"],["descripcion_del_estacionamiento","VARCHAR","","DESCRIPCION_DEL_Estacionamiento","x4 (bienes_raices)","ambos","Se indicará si es un estacionamiento. S : Si N : No"],["descripcion_del_terreno","VARCHAR","","DESCRIPCION_DEL_Terreno","x4 (bienes_raices)","ambos","Se indicará si es un terreno. S : Si N : No"],["descripcion_del_casa","VARCHAR","","DESCRIPCION_DEL_Casa","x4 (bienes_raices)","ambos","Se indicará si es una casa. S : Si N : No"],["descripcion_del_edificio","VARCHAR","","DESCRIPCION_DEL_Edificio","x4 (bienes_raices)","ambos","Se indicará si es un edificio. S : Si N : No"],["descripcion_del_piso_completo_de_edificio","VARCHAR","","DESCRIPCION_DEL_Piso completo de edificio","x4 (bienes_raices)","ambos","Se indicará si es un piso completo del edificio. S : Si N : No"],["descripcion_del_piso_incompleto_de_edificio","VARCHAR","","DESCRIPCION_DEL_Piso incompleto de edificio","x4 (bienes_raices)","ambos","Se indicará si es un piso incompleto del edificio. S : Si N : No"],["descripcion_del_departamento","VARCHAR","","DESCRIPCION_DEL_Departamento","x4 (bienes_raices)","ambos","Se indicará si es un departamento. S : Si N : No"],["descripcion_del_obra_en_construccion","VARCHAR","","DESCRIPCION_DEL_Obra en construcción","x4 (bienes_raices)","ambos","Se indicará si es una obra en construcción. S : Si N : No"],["descripcion_del_otros","VARCHAR","","DESCRIPCION_DEL_Otros","x4 (bienes_raices)","ambos","Se indicará si es otros. S : Si N : No Ejemplos: 1. Si el bien raíz es una casa, se informará con una S en el campo CASA, y todos los otros campos deberán informarse con una N. 2. En caso que la compañía tenga contabilizado un local, una oficina y una bodega con un mismo rol, se deberá informar de la siguiente manera: Local : S Oficina : S Bodega : S Estacionamiento : N Terreno : N"],["tipo_de_inmueble","VARCHAR","","TIPO_DE_INMUEBLE","x4 (bienes_raices)","ambos","Corresponde señalar si el bien raíz es urbano o no urbano. Se informará de acuerdo a la siguiente codificación: UR : Urbano UN : No urbano"],["destino","VARCHAR","","DESTINO","x4 (bienes_raices)","ambos","Corresponde indicar si el bien raíz es \"Habitacional\" o \"No Habitacional\". Se informara de acuerdo a la siguiente codificación: HA : Habitacional NH : No habitacional"],["uso","VARCHAR","","USO","x4 (bienes_raices)","ambos","Corresponde indicar el uso que se le da al bien raíz, es decir si se arrienda con el fin de obtener una renta o es ocupado para desarrollar la actividad de seguros. En caso que una compañía tenga un bien raíz y una parte esté dada en arriendo y otra para uso propio y contablemente esté registrado como un sólo bien, se deberá informar como uso mixto. Se informará de acuerdo a la codificación definida en SEIL, codificación S.V.S"],["porcentaje_uso_propio","DOUBLE","","PORCENTAJE_USO_PROPIO","x4 (bienes_raices)","ambos","Corresponde informar cuando el uso es mixto, qué porcentaje del bien raíz está destinado para uso propio"],["ubicacion","VARCHAR","","UBICACIÓN","x4 (bienes_raices)","ambos","Corresponde señalar la dirección exacta del bien raíz"],["saldo_plazo_arriendo","BIGINT","","SALDO_PLAZO_ARRIENDO","x4 (bienes_raices)","ambos","Se deberá informar los meses restantes del contrato de arriendo a contar de la fecha de información. En el caso de los bienes raíces de uso propio se debe informar en cero (0)"],["monto_arriendo_uf","DOUBLE","UF","MONTO_ARRIENDO","x4 (bienes_raices)","ambos","Para los bienes raíces en arriendo, corresponde informar el monto de arriendo mensual expresado en UF. En el caso de los bienes raíces de uso propio y de los leasing se debe informar en cero (0)"],["costo_historico_corregido_m_clp","BIGINT","miles de pesos","COSTO_HISTORICO_C_ORREGIDO","x4 (bienes_raices)","ambos","Corresponde señalar el valor de adquisición del bien raíz expresado en miles de pesos (M$)"],["depreciacion_acumulada_m_clp","BIGINT","miles de pesos","DEPRECIACION_ACUMULADA","x4 (bienes_raices)","ambos","Corresponde señalar el monto de depreciación acumulada del bien raíz a la fecha de cierre del mes a que se refiere la información, expresada en miles de pesos (M$)"],["valor_contable_m_clp","BIGINT","miles de pesos","VALOR_CONTABLE","x4 (bienes_raices)","ambos","Corresponde al costo histórico menos depreciación acumulada, en miles de pesos (M$)"],["valor_tasacion_m_clp","BIGINT","miles de pesos","VALOR_TASACION","x4 (bienes_raices)","ambos","Corresponde al valor, en miles de pesos (M$), de la última tasación efectuada, conforme a lo señalado en Norma de Carácter General Nº42 o la que la reemplace"],["fecha_de_tasacion","VARCHAR","","FECHA_DE_TASACION","x4 (bienes_raices)","ambos","Corresponde señalar la fecha en que se efectuó la tasación. Se deberá informar en el siguiente formato: AAAAMMDD"],["nombre_filial","VARCHAR","","NOMBRE_FILIAL","x5 (filiales)","ambos","Corresponde señalar el nombre de la sociedad filial"],["participacion_porcentual","DOUBLE","","PARTICIPACION_PORCENTUAL","x5 (filiales)","ambos","Corresponde señalar el porcentaje de participación del inversionista en la sociedad filial a la fecha de cierre del mes a que se refiere la información"],["patrimonio_filial_m_clp","BIGINT","miles de pesos","PATRIMONIO_FILIAL","x5 (filiales)","ambos","Corresponde informar el patrimonio contable de la filial a la fecha de cierre de los estados financieros para los meses de marzo, junio, septiembre y diciembre. Para los otros períodos se debe informar el patrimonio contable de la filial del trimestre anterior al período informado. Esta información deberá expresarse en miles de pesos (M$)"],["resultado_de_la_sociedad_filial_m_clp","BIGINT","miles de pesos","RESULTADO_DE_LA_SOCIEDAD_FILIAL","x5 (filiales)","ambos","Corresponde informar el resultado (utilidad o pérdida) contable de la filial a la fecha de cierre de los estados financieros para los meses de marzo, junio, septiembre y diciembre. Para los otros períodos se debe informar el resultado contable de la filial del trimestre anterior al período informado. Esta información deberá expresarse en miles de pesos (M$)"],["fecha_estados_financieros","VARCHAR","","FECHA_ESTADOS_FINANCIEROS","x5 (filiales)","ambos","Corresponde señalar la fecha de cierre de los últimos estados financieros de la filial, utilizados para determinar el Valor Patrimonial Proporcional, VPP. Se deberá informar con el siguiente formato: AAAAMMDD"],["valor_de_mercado_m_clp","BIGINT","miles de pesos","VALOR_DE_MERCADO","x5 (filiales)","ambos","Corresponde al valor de mercado del instrumento a la fecha de la información. Se debe presentar en M$. Para las inversiones que no se transen en un mercado primario o secundario, se deberá informar una estimación del valor de mercado realizada por la compañía"],["mayor_o_menor_valor_de_inversiones_m_clp","BIGINT","miles de pesos","MAYOR_O_MENOR_VALOR_DE_INVERSIONES","x5 (filiales)","ambos","Corresponde al mayor o menor valor determinado entre el costo de adquisición y su VPP, ambos conceptos definidos en la Circular de Valorización de Inversiones, en miles de pesos (M$). Cuando corresponda a un menor valor de inversiones, la cantidad se colocará negativa y si es un mayor valor, se colocará positiva"],["pais_matriz","VARCHAR","","PAIS_MATRIZ","x2 (deuda), x3 (acciones_y_fondos)","desde 2024-12","Corresponde señalar el país donde reside la casa matriz del emisor del instrumento. Se informará de acuerdo a la codificación definida en SEIL, Codificación CMF, Países"],["plazo_al_vencimiento","BIGINT","","PLAZO_AL_VENCIMIENTO","x2 (deuda)","desde 2024-12","Se deberá informar los meses restantes al vencimiento del instrumento a contar de la fecha de información"],["duracion","DOUBLE","","DURACIÓN","x2 (deuda)","desde 2024-12","Corresponde al promedio ponderado en años de los vencimientos de sus flujos de caja, donde los ponderadores son el valor presente de cada flujo como una proporción del precio del instrumento"],["tipo_amortizacion","BIGINT","","TIPO_AMORTIZACIÓN","x2 (deuda)","desde 2024-12","Corresponde informar el tipo amortización del instrumento de renta fija, de acuerdo a la siguiente clasificación: 1: Cero 2: Francés 3: Bullet 4: Baloon 0: Otra"],["incremento_riesgo","VARCHAR","","INCREMENTO_RIESGO","x2 (deuda)","desde 2024-12","Corresponde informar si la situación del riesgo crediticio del instrumento financiero se ha incrementado significativamente desde el reconocimiento inicial, según lo instruido en la materia por la NCG N°311 e IFRS 9: S : Si el riesgo crediticio del instrumento financiero SI se ha incrementado significativamente. N : Si el riesgo crediticio del instrumento financiero NO se ha incrementado significativamente"],["efecto_patrimonio","VARCHAR","","EFECTO_PATRIMONIO","x2 (deuda), x3 (acciones_y_fondos)","desde 2024-12","Corresponde informar si una inversión, es valorizada a Valor razonable (VR) con cambios en otro resultado integral: SI: Con cambios en otro resultado integral. NO: Sin cambios en otro resultado integral. NA: Inversión valorizada a Costo Amortizado"],["rut_fondo_p","VARCHAR","","RUT_FONDO_P","x3 (acciones_y_fondos)","desde 2024-12","Para instrumentos de tipo CFIIEP y CFIIEPOIED, constituidos en el país, se debe informar el RUT asociado. Para instrumentos distintos a CFIIEP y CFIIEPOIED, se debe completar este campo con ceros"],["nombre_fondo_p","VARCHAR","","NOMBRE_FONDO_P","x3 (acciones_y_fondos)","desde 2024-12","Para instrumentos de tipo CFIIEP y CFIIEPOIED, constituidos en el país, se debe informar el nombre del Fondo. Para instrumentos distintos a CFIIEP y CFIIEPOIED, se debe informar “NO APLICA”"],["segmento_fondo","VARCHAR","","SEGMENTO_FONDO","x3 (acciones_y_fondos)","desde 2024-12","Para los fondos de inversiones corresponde informar el segmento del fondo según la siguiente clasificación: 01: Accionarios; Fondos cuyas inversiones en al menos un 70% sean acciones de sociedades anónimas abiertas nacionales o extranjeras. 02: Capital Privado; Fondos cuyas inversiones en al menos un 70% sean acciones de empresas cerradas nacionales o extranjeras. 03: Deuda; Fondos cuyas inversiones en al menos un 70% correspondan a instrumentos de deuda nacionales o extranjeros, transados en bolsa. 04: Deuda Privada; Fondos cuyas inversiones en al menos un 70% sean en instrumentos de deuda que no se transan en mercados públicos, y que no estén ligados al sector inmobiliario ni de obras de infraestructura. En esta categoría, por ejemplo, se incluyen los fondos que invierten en facturas, leasing operativo, deudas"],["tipo_inmobiliario","VARCHAR","","TIPO_INMOBILIARIO","x3 (acciones_y_fondos)","desde 2024-12","Corresponde informar, para inversiones con riesgo subyacente de tipo inmobiliario, el tipo de inversión inmobiliaria según la siguiente clasificación: 80 01: Renta Habitacional (Residencial): Corresponden a aquellos fondos que tienen por objetivo principal invertir en bienes raíces habitacionales, con el fin de darlos en arriendo. 02: Renta No Habitacional: Corresponden a aquellos fondos que tienen como objetivo principal invertir en todo tipo de negocios inmobiliarios destinados a la renta no residencial. 03: Renta Mixta: Corresponden a aquellos fondos que tienen como objetivo principal invertir en alguna combinación de los números 1) y 2) anteriores. 04: Desarrollo Residencial: Corresponden a aquellos fondos cuyo objetivo principal sea invertir en el desarrollo de bienes raíces para"],["subyacente","VARCHAR","","SUBYACENTE","x3 (acciones_y_fondos)","desde 2024-12","Corresponde informar los activos subyacentes de los fondos de inversión. Solo se informarán los tipos de activos cuya participación en la cartera de inversiones del fondo sea superior o igual al 10%. Se debe informar la combinación de caracteres según el siguiente listado, seleccionado la o las letras correspondientes al tipo de activo, con un máximo de 10 y un mínimo de 1. En caso de sobrar caracteres, deberá rellenarse con espacios. D: Depósitos. I: Instrumentos emitidos por Estados o Bancos Centrales. B: Bonos emitidos por empresas o bancos. P: Pagarés. 81 M: Mutuos hipotecarios. H: Letras hipotecarias. L: Leasings"],["cuotas_suscritas","BIGINT","","CUOTAS_SUSCRITAS","x3 (acciones_y_fondos)","desde 2024-12","Para los fondos mutuos y de inversión constituidos fuera del país y fondos de inversión constituidos en el país, cuyos activos estén invertidos en valores extranjeros, corresponde informar el número de cuotas suscritas y pagadas del fondo. Para inversiones que no corresponda informar datos, se deberá completar con ceros"],["porcentaje_participacion","DOUBLE","","PORCENTAJE_PARTICI_PACION","x3 (acciones_y_fondos)","desde 2024-12","Corresponde Informar el porcentaje de participación de la compañía respecto a las cuotas suscritas y pagadas del fondo en aquellos casos que corresponda informar datos en el campo CUOTAS_SUSCRITAS. Para inversiones que no corresponda informar datos, se deberá completar con ceros"],["simultanea","VARCHAR","","SIMULTANEA","x3 (acciones_y_fondos)","desde 2024-12","Corresponde informar si una o más acciones o cuotas de fondos registradas forman parte de una operación simultánea. Se informará de acuerdo a la siguiente codificación: CVS : acción o cuota de fondo afecta a operación simultánea. NVS : acción o cuota de fondo no afecta a operación simultánea"],["total_m2_terreno","BIGINT","","TOTAL_M2_TERRENO","x4 (bienes_raices)","desde 2024-12","Para todos los bienes raíces informados, se deberá indicar el total de m2 del terreno. Para el caso de departamentos u oficinas en un edificio, se debe informar con ceros"],["total_m2_construccion","BIGINT","","TOTAL_M2_CONSTRU_CCION","x4 (bienes_raices)","desde 2024-12","Corresponde informar el total de m2 construidos del bien raíz"],["valor_tasacion_terreno_m2","DOUBLE","","VALOR_TASACION_TE_RRENO_M2","x4 (bienes_raices)","desde 2024-12","Corresponde informar el valor por metro cuadrado del terreno, obtenido a partir de la menor tasación de la propiedad. Si la tasación no presenta separada la valorización del terreno y la construcción, se debe informar con ceros. La información deberá ser reportada en la moneda de origen informada en el campo MONEDA. Para el caso de departamentos u oficinas en un edificio, se debe informar con ceros"],["valor_tasacion_construccion_m2","DOUBLE","","VALOR_TASACION_CO_NSTRUCCION_M2","x4 (bienes_raices)","desde 2024-12","Corresponde informar el valor por metro cuadrado de la construcción, obtenido a partir de la menor tasación de la propiedad. Si la tasación no presenta separada la valorización del terreno y la construcción, se debe informar con ceros. La información deberá ser reportada en la moneda de origen informada en el campo MONEDA"]]}};
window.DICCIONARIO_SEGUROS_TOTAL = 482;
